@dataclass(frozen=True)
class MasterExtractResult:
    name: str
    output_path: Path
    rows: int
    columns: tuple[str, ...]


_EXCLUSION_POLICY_SOURCE = '"""Sheet-level exclusion semantics for MI Master strategic markets.\n\nThe MI Master uses the same visible marker ("제외") with different meanings\nper sheet.  Column-position heuristics are not reliable enough because some\nrow-exclusion sheets put the marker in Class-like columns, while class-only\nexclusion sheets must keep the row in the market denominator.\n"""\n\nfrom __future__ import annotations\n\nimport re\nimport unicodedata\nfrom typing import Any, Literal\n\nExclusionMode = Literal["row", "class", "dimension_na", "none", "legacy"]\n\nROW_EXCLUSION_MARKETS = frozenset({"strategy_006", "strategy_007", "strategy_009"})\nCLASS_EXCLUSION_MARKETS = frozenset({"strategy_013", "strategy_016"})\nDIMENSION_NA_EXCLUSION_MARKETS = frozenset({"strategy_014"})\nNO_EXCLUSION_MARKETS = frozenset({\n    "strategy_001",\n    "strategy_002",\n    "strategy_003",\n    "strategy_004",\n    "strategy_005",\n    "strategy_008",\n    "strategy_010",\n    "strategy_011",\n    "strategy_012",\n    "strategy_015",\n})\n\nEXCLUSION_MODE_BY_MARKET_ID: dict[str, ExclusionMode] = {\n    **{market_id: "row" for market_id in ROW_EXCLUSION_MARKETS},\n    **{market_id: "class" for market_id in CLASS_EXCLUSION_MARKETS},\n    **{market_id: "dimension_na" for market_id in DIMENSION_NA_EXCLUSION_MARKETS},\n    **{market_id: "none" for market_id in NO_EXCLUSION_MARKETS},\n}\n\nEXCLUSION_MODE_BY_SHEET_NAME: dict[str, ExclusionMode] = {\n    "리바로 리바로젯": "row",\n    "리바로페노": "row",\n    "트루패스 피나스타 제이다트": "row",\n    "헴리브라": "class",\n    "플라주오피": "class",\n    "위너프 위너프A+": "dimension_na",\n    "위너프 위너프에이플러스": "dimension_na",\n    "라베칸 라베칸듀오": "none",\n    "제이클": "none",\n    "가드렛 가드메트": "none",\n    "타발리스": "none",\n    "시그마트": "none",\n    "리바로하이 리바로브이": "none",\n    "뉴트로진 모빌리아": "none",\n    "악템라": "none",\n    "페린젝트 베노훼럼": "none",\n    "엔커버": "none",\n}\n\n\ndef clean_text(value: Any) -> str | None:\n    if value is None:\n        return None\n    text = unicodedata.normalize("NFC", str(value)).strip()\n    if not text or text.lower() == "nan":\n        return None\n    return text.replace("위너프A+", "위너프에이플러스")\n\n\ndef contains_exclusion_marker(value: Any) -> bool:\n    text = clean_text(value)\n    return bool(text and "제외" in text and not text.startswith("비제외"))\n\n\ndef _normalize_sheet_name(value: Any) -> str | None:\n    text = clean_text(value)\n    return re.sub(r"\\s+", " ", text) if text else None\n\n\ndef exclusion_mode_for_market(\n    *,\n    strategic_market_id: str | None = None,\n    sheet_name: str | None = None,\n    default: ExclusionMode = "legacy",\n) -> ExclusionMode:\n    market_id = str(strategic_market_id or "").strip()\n    if market_id in EXCLUSION_MODE_BY_MARKET_ID:\n        return EXCLUSION_MODE_BY_MARKET_ID[market_id]\n\n    normalized_sheet = _normalize_sheet_name(sheet_name)\n    if normalized_sheet and normalized_sheet in EXCLUSION_MODE_BY_SHEET_NAME:\n        return EXCLUSION_MODE_BY_SHEET_NAME[normalized_sheet]\n    return default\n\n\ndef classify_exclusion_cells(\n    values: list[Any] | tuple[Any, ...],\n    *,\n    class_indexes: set[int] | None = None,\n    strategic_market_id: str | None = None,\n    sheet_name: str | None = None,\n    default: ExclusionMode = "legacy",\n) -> tuple[bool, bool]:\n    """Return (row_excluded, class_excluded) using sheet-level semantics."""\n\n    marker_indexes = [idx for idx, value in enumerate(values) if contains_exclusion_marker(value)]\n    if not marker_indexes:\n        return False, False\n\n    mode = exclusion_mode_for_market(\n        strategic_market_id=strategic_market_id,\n        sheet_name=sheet_name,\n        default=default,\n    )\n    if mode == "row":\n        return True, False\n    if mode == "class":\n        return False, True\n    if mode in {"dimension_na", "none"}:\n        return False, False\n\n    class_indexes = set(class_indexes or ())\n    row_excluded = False\n    class_excluded = False\n    for idx in marker_indexes:\n        if idx in class_indexes:\n            class_excluded = True\n        else:\n            row_excluded = True\n    return row_excluded, class_excluded\n'

_PROTOTYPE_CACHE: dict[str, types.ModuleType] = {}


def _load_policy_module() -> types.ModuleType:
    module = types.ModuleType("strategic_exclusion_policy")
    module.__file__ = "<archived strategic_exclusion_policy from main:pipeline/scripts>"
    module.__dict__["__name__"] = module.__name__
    exec(compile(_EXCLUSION_POLICY_SOURCE, module.__file__, "exec"), module.__dict__)
    return module


def _load_prototype(name: str, source: str) -> types.ModuleType:
    if name in _PROTOTYPE_CACHE:
        return _PROTOTYPE_CACHE[name]

    module = types.ModuleType(f"pipeline.etl.io.catalog._archived_{name}")
    module.__file__ = f"<archived {name} from main:pipeline/scripts>"
    module.__dict__["__name__"] = module.__name__

    storage_module = types.ModuleType("storage")
    storage_module.get_mi_master_path = get_mi_master_path
    policy_module = _load_policy_module()
    previous_storage = sys.modules.get("storage")
    previous_policy = sys.modules.get("strategic_exclusion_policy")
    previous_pipeline_policy = sys.modules.get("pipeline.scripts.strategic_exclusion_policy")
    previous_module = sys.modules.get(module.__name__)
    sys.modules["storage"] = storage_module
    sys.modules["strategic_exclusion_policy"] = policy_module
    sys.modules["pipeline.scripts.strategic_exclusion_policy"] = policy_module
    sys.modules[module.__name__] = module
    try:
        exec(compile(source, module.__file__, "exec"), module.__dict__)
    finally:
        if previous_storage is None:
            sys.modules.pop("storage", None)
        else:
            sys.modules["storage"] = previous_storage
        if previous_policy is None:
            sys.modules.pop("strategic_exclusion_policy", None)
        else:
            sys.modules["strategic_exclusion_policy"] = previous_policy
        if previous_pipeline_policy is None:
            sys.modules.pop("pipeline.scripts.strategic_exclusion_policy", None)
        else:
            sys.modules["pipeline.scripts.strategic_exclusion_policy"] = previous_pipeline_policy
        if previous_module is None:
            sys.modules.pop(module.__name__, None)
        else:
            sys.modules[module.__name__] = previous_module

    _PROTOTYPE_CACHE[name] = module
    return module


def _output(root: Path, relative: str) -> Path:
    return Path(root) / relative


def _pin_ingested_at(module: types.ModuleType, ingested_at: str | None) -> None:
    if ingested_at and hasattr(module, "utc_now_text"):
        module.utc_now_text = lambda: ingested_at


def _result(name: str, output_path: Path) -> MasterExtractResult:
    table = pq.read_table(output_path)
    return MasterExtractResult(
        name=name,
        output_path=output_path,
        rows=table.num_rows,
        columns=tuple(table.schema.names),
    )


_SOURCE_P07 = '"""\nprototype_07_master_market_definition_to_parquet.py\n===================================================\nMI Master "시장정의 & Target" sheet -> Parquet.\n\nPhase 09a policy:\n- Canonical logic: /Users/rexxa/github/jw-market/etl/master_market_definition.py\n- Canonical schema: /Users/rexxa/github/jw-market/sql/schema_master.sql,\n  stg_master_market_definition\n- Output schema is DDL columns only. No prototype helper columns such as\n  source_files or period are added.\n- Q&A sheet and JW major product list are intentionally not parsed in 09a.\n\nUsage, in Step D after user review:\n    python3 scripts/prototype_07_master_market_definition_to_parquet.py\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport re\nimport sys\nfrom datetime import date, datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import Path\nfrom typing import Any, Iterable\n\ntry:\n    import pyarrow as pa\n    import pyarrow.parquet as pq\n    from openpyxl import load_workbook\nexcept ImportError as e:\n    sys.exit(f"ERROR: {e}\\n  pip3 install pyarrow openpyxl --break-system-packages")\n\n\nETL_DIR = Path(__file__).resolve().parent / "etl"\nsys.path.insert(0, str(ETL_DIR))\nfrom storage import get_mi_master_path  # noqa: E402\n\n\nDEFAULT_INPUT_FILE = get_mi_master_path()\nDEFAULT_OUTPUT_FILE = Path("parquet/master_market_definition/master_market_definition.parquet")\nSOURCE_SHEET = "시장정의 & Target"\n\nMASTER_MARKET_DEFINITION_COLUMNS = (\n    "strategic_market_id",\n    "market_name",\n    "source_type",\n    "market_atc_codes_json",\n    "full_market_atc4_codes_json",\n    "direct_competition_brands_json",\n    "description",\n    "analysis_levels_json",\n    "analysis_level_funnel",\n    "analysis_level_etc",\n    "target_customer_priority_json",\n    "raw_row_json",\n    "source_sheet",\n    "source_file_version",\n    "ingested_at",\n)\n\nMARKET_BY_ID = {\n    "strategy_001": {"sheet_name": "라베칸 라베칸듀오", "source_type": "UBIST"},\n    "strategy_002": {"sheet_name": "제이클", "source_type": "IQVIA"},\n    "strategy_003": {"sheet_name": "가드렛 가드메트", "source_type": "IQVIA"},\n    "strategy_004": {"sheet_name": "타발리스", "source_type": "IQVIA"},\n    "strategy_005": {"sheet_name": "시그마트", "source_type": "IQVIA"},\n    "strategy_006": {"sheet_name": "리바로 리바로젯", "source_type": "UBIST"},\n    "strategy_007": {"sheet_name": "리바로페노", "source_type": "UBIST"},\n    "strategy_008": {"sheet_name": "리바로하이 리바로브이", "source_type": "UBIST"},\n    "strategy_009": {"sheet_name": "트루패스 피나스타 제이다트", "source_type": "UBIST"},\n    "strategy_010": {"sheet_name": "뉴트로진 모빌리아", "source_type": "IQVIA"},\n    "strategy_011": {"sheet_name": "악템라", "source_type": "IQVIA"},\n    "strategy_012": {"sheet_name": "페린젝트 베노훼럼", "source_type": "IQVIA"},\n    "strategy_013": {"sheet_name": "헴리브라", "source_type": "IQVIA"},\n    "strategy_014": {"sheet_name": "위너프 위너프A+", "source_type": "IQVIA"},\n    "strategy_015": {"sheet_name": "엔커버", "source_type": "IQVIA"},\n    "strategy_016": {"sheet_name": "플라주오피", "source_type": "IQVIA"},\n}\n\n# 1-based column indexes in sheet "시장정의 & Target".\nMARKET_DEFINITION_COLUMNS: dict[str, tuple[int, ...]] = {\n    "strategy_001": (3,),\n    "strategy_002": (4,),\n    "strategy_003": (5,),\n    "strategy_004": (6,),\n    "strategy_005": (7,),\n    "strategy_006": (8,),\n    "strategy_007": (9,),\n    "strategy_008": (10, 11),\n    "strategy_009": (12, 13),\n    "strategy_010": (14, 15),\n    "strategy_011": (16,),\n    "strategy_012": (17, 18),\n    "strategy_013": (19,),\n    "strategy_015": (20,),\n    "strategy_014": (21,),\n    "strategy_016": (22,),\n}\n\nMARKET_DESCRIPTIONS = {\n    "strategy_015": "IQVIA 기준 하모닐란과 엔커버 2개의 PRODUCT NAME KOR 에 대해 PACK DESC 를 하위분류로 4가지로 분석",\n}\n\nANALYSIS_LEVEL_ROWS = {\n    14: "Class",\n    15: "Molecule",\n    16: "Brand",\n    17: "Dosage Form",\n    18: "Strength",\n    19: "Etc",\n}\nFULL_MARKET_ROWS = range(22, 45)\nDIRECT_COMPETITION_ROWS = range(48, 51)\nTARGET_CUSTOMER_ROWS = range(54, 58)\nMETRIC_ROWS = range(61, 65)\n\nEXPECTED_STRATEGIC_MARKET_IDS = tuple(MARKET_DEFINITION_COLUMNS.keys())\n\nATC_CODE_PATTERN = r"[A-Z]\\d{0,2}[A-Z](?:\\d{0,2})?"\nATC_BRACKET_RE = re.compile(rf"\\[({ATC_CODE_PATTERN})\\]")\nATC_PLAIN_RE = re.compile(rf"^({ATC_CODE_PATTERN})\\b")\n\n\ndef utc_now_text() -> str:\n    return datetime.now(timezone.utc).replace(tzinfo=None).isoformat(sep=" ", timespec="seconds")\n\n\ndef to_jsonable(value: Any) -> Any:\n    if isinstance(value, (datetime, date)):\n        return value.isoformat()\n    if isinstance(value, Decimal):\n        return float(value)\n    return value\n\n\ndef dumps_json(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, default=to_jsonable, sort_keys=True)\n\n\ndef cell_text(value: object) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    return text or None\n\n\ndef atc_code_from_text(value: object) -> str | None:\n    text = cell_text(value)\n    if not text:\n        return None\n    bracket_match = ATC_BRACKET_RE.search(text)\n    if bracket_match:\n        return bracket_match.group(1)\n    plain_match = ATC_PLAIN_RE.match(text)\n    if plain_match:\n        return plain_match.group(1)\n    return None\n\n\ndef find_atc_column(ws) -> int | None:\n    for column_id in range(1, 12):\n        for row_id in range(3, 9):\n            value = ws.cell(row_id, column_id).value\n            if value and "ATC" in str(value).upper():\n                return column_id\n    return None\n\n\ndef extract_atc_from_market_sheet(wb, sheet_name: str) -> list[str]:\n    """Extract normalized ATC codes from a market sheet\'s ATC column."""\n    if sheet_name not in wb.sheetnames:\n        return []\n    ws = wb[sheet_name]\n    atc_column = find_atc_column(ws)\n    if atc_column is None:\n        return []\n\n    codes: set[str] = set()\n    for (value,) in ws.iter_rows(\n        min_row=6,\n        max_row=ws.max_row,\n        min_col=atc_column,\n        max_col=atc_column,\n        values_only=True,\n    ):\n        code = atc_code_from_text(value)\n        if code:\n            codes.add(code)\n    return sorted(codes)\n\n\ndef blank_record() -> dict[str, Any]:\n    return {column: None for column in MASTER_MARKET_DEFINITION_COLUMNS}\n\n\ndef source_type_from_values(values: list[str | None], fallback: str) -> str:\n    joined = " ".join(value or "" for value in values).lower()\n    if "ubist" in joined and "iqvia" in joined:\n        return "BOTH"\n    if "ubist" in joined:\n        return "UBIST"\n    if "iqvia" in joined:\n        return "IQVIA"\n    return fallback\n\n\ndef values_for_rows(ws, rows: range, columns: tuple[int, ...]) -> list[dict[str, Any]]:\n    values: list[dict[str, Any]] = []\n    for row_id in rows:\n        row_label = cell_text(ws.cell(row_id, 2).value) or cell_text(ws.cell(row_id, 1).value)\n        for column_id in columns:\n            value = ws.cell(row_id, column_id).value\n            if value is None or str(value).strip() == "":\n                continue\n            values.append(\n                {\n                    "row_id": row_id,\n                    "label": row_label,\n                    "column_id": column_id,\n                    "product_name": cell_text(ws.cell(6, column_id).value),\n                    "value": to_jsonable(value),\n                }\n            )\n    return values\n\n\ndef analysis_levels(ws, columns: tuple[int, ...]) -> dict[str, Any]:\n    levels: dict[str, Any] = {}\n    for row_id, level_name in ANALYSIS_LEVEL_ROWS.items():\n        by_product: dict[str, Any] = {}\n        values: list[Any] = []\n        for column_id in columns:\n            product_name = cell_text(ws.cell(6, column_id).value) or f"col_{column_id}"\n            value = to_jsonable(ws.cell(row_id, column_id).value)\n            by_product[product_name] = value\n            if value not in (None, ""):\n                values.append(value)\n        levels[level_name] = {\n            "by_product": by_product,\n            "values": values,\n        }\n    levels["Metrics"] = values_for_rows(ws, METRIC_ROWS, columns)\n    return levels\n\n\ndef target_customer_priority(ws, columns: tuple[int, ...]) -> list[dict[str, Any]]:\n    return values_for_rows(ws, TARGET_CUSTOMER_ROWS, columns)\n\n\ndef raw_payload_for_market(ws, columns: tuple[int, ...]) -> dict[str, Any]:\n    payload_columns = []\n    for column_id in columns:\n        values = []\n        for row_id in range(5, 65):\n            label = cell_text(ws.cell(row_id, 2).value) or cell_text(ws.cell(row_id, 1).value)\n            cell_value = ws.cell(row_id, column_id).value\n            if label is None and (cell_value is None or str(cell_value).strip() == ""):\n                continue\n            values.append(\n                {\n                    "row_id": row_id,\n                    "label": label,\n                    "value": to_jsonable(cell_value),\n                }\n            )\n        payload_columns.append(\n            {\n                "column_id": column_id,\n                "team": cell_text(ws.cell(5, column_id).value),\n                "product_name": cell_text(ws.cell(6, column_id).value),\n                "values": values,\n            }\n        )\n    return {"source_sheet": SOURCE_SHEET, "columns": payload_columns}\n\n\ndef iter_market_definition_rows(xlsx_path: Path, ingested_at: str | None = None) -> Iterable[dict[str, Any]]:\n    timestamp = ingested_at or utc_now_text()\n    wb = load_workbook(xlsx_path, read_only=True, data_only=True)\n    try:\n        if SOURCE_SHEET not in wb.sheetnames:\n            raise ValueError(f"required sheet not found: {SOURCE_SHEET!r}; sheets={wb.sheetnames}")\n        ws = wb[SOURCE_SHEET]\n\n        for strategic_market_id, columns in MARKET_DEFINITION_COLUMNS.items():\n            config = MARKET_BY_ID[strategic_market_id]\n            source_values = [cell_text(ws.cell(10, column).value) for column in columns]\n            market_atc_codes = extract_atc_from_market_sheet(wb, config["sheet_name"])\n            full_market_values = values_for_rows(ws, FULL_MARKET_ROWS, columns)\n            direct_competition_values = values_for_rows(ws, DIRECT_COMPETITION_ROWS, columns)\n            levels = analysis_levels(ws, columns)\n            customer_priority = target_customer_priority(ws, columns)\n            etc_values = levels.get("Etc", {}).get("values", [])\n\n            record = blank_record()\n            record.update(\n                {\n                    "strategic_market_id": strategic_market_id,\n                    "market_name": config["sheet_name"],\n                    "source_type": source_type_from_values(source_values, config["source_type"]),\n                    "market_atc_codes_json": dumps_json(market_atc_codes),\n                    "full_market_atc4_codes_json": dumps_json(full_market_values),\n                    "direct_competition_brands_json": dumps_json(direct_competition_values),\n                    "description": MARKET_DESCRIPTIONS.get(strategic_market_id),\n                    "analysis_levels_json": dumps_json(levels),\n                    "analysis_level_funnel": "O" if strategic_market_id == "strategy_001" else None,\n                    "analysis_level_etc": "; ".join(str(value).strip() for value in etc_values if value),\n                    "target_customer_priority_json": dumps_json(customer_priority),\n                    "raw_row_json": dumps_json(raw_payload_for_market(ws, columns)),\n                    "source_sheet": SOURCE_SHEET,\n                    "source_file_version": xlsx_path.name,\n                    "ingested_at": timestamp,\n                }\n            )\n            yield record\n    finally:\n        wb.close()\n\n\ndef validate_records(records: list[dict[str, Any]]) -> None:\n    if len(records) != 16:\n        raise ValueError(f"market_definition row count must be 16, found {len(records)}")\n\n    ids = [record["strategic_market_id"] for record in records]\n    if len(set(ids)) != 16:\n        raise ValueError(f"strategic_market_id must be unique, found duplicate ids: {ids}")\n    if tuple(ids) != EXPECTED_STRATEGIC_MARKET_IDS:\n        raise ValueError(\n            "strategic_market_id order/mapping mismatch: "\n            f"expected={EXPECTED_STRATEGIC_MARKET_IDS}, actual={tuple(ids)}"\n        )\n\n    for index, record in enumerate(records, start=1):\n        extra_columns = sorted(set(record) - set(MASTER_MARKET_DEFINITION_COLUMNS))\n        missing_columns = sorted(set(MASTER_MARKET_DEFINITION_COLUMNS) - set(record))\n        if extra_columns or missing_columns:\n            raise ValueError(\n                f"row {index} schema mismatch: extra={extra_columns}, missing={missing_columns}"\n            )\n        for column in (\n            "market_atc_codes_json",\n            "full_market_atc4_codes_json",\n            "direct_competition_brands_json",\n            "analysis_levels_json",\n            "target_customer_priority_json",\n            "raw_row_json",\n        ):\n            json.loads(record[column])\n\n\ndef write_parquet(records: list[dict[str, Any]], output_file: Path) -> None:\n    output_file.parent.mkdir(parents=True, exist_ok=True)\n    schema = pa.schema([pa.field(column, pa.string()) for column in MASTER_MARKET_DEFINITION_COLUMNS])\n    table = pa.Table.from_pylist(records, schema=schema)\n    pq.write_table(table, output_file, compression="zstd", compression_level=3)\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--input-file", default=str(DEFAULT_INPUT_FILE))\n    parser.add_argument("--output-file", default=str(DEFAULT_OUTPUT_FILE))\n    args = parser.parse_args()\n\n    input_file = Path(args.input_file)\n    output_file = Path(args.output_file)\n    if not input_file.exists():\n        sys.exit(f"ERROR: input file not found: {input_file}")\n\n    print("=" * 72)\n    print("MI Master market_definition -> Parquet")\n    print("=" * 72)\n    print(f"  input file:   {input_file}")\n    print(f"  source sheet: {SOURCE_SHEET}")\n    print(f"  output file:  {output_file}")\n    print(f"  columns:      {len(MASTER_MARKET_DEFINITION_COLUMNS)} DDL columns")\n    print("  helpers:      none")\n\n    records = list(iter_market_definition_rows(input_file))\n    validate_records(records)\n    write_parquet(records, output_file)\n\n    print("\\nResult")\n    print(f"  rows:                   {len(records)}")\n    print(f"  unique strategic ids:   {len({row[\'strategic_market_id\'] for row in records})}")\n    print(f"  output size:            {output_file.stat().st_size / 1024:.1f} KB")\n    print(f"  ingested_at:            {records[0][\'ingested_at\'] if records else None}")\n    print("\\nDone")\n\n\nif __name__ == "__main__":\n    main()\n'

_SOURCE_P08 = '"""\nprototype_08_master_qa_to_parquet.py\n====================================\nMI Master "Q&A" sheet -> Parquet.\n\nPhase 09b policy:\n- Canonical logic: /Users/rexxa/github/jw-market/etl/master_qa.py\n- Canonical schema: /Users/rexxa/github/jw-market/sql/schema_master.sql,\n  stg_master_qa\n- Output schema is DDL columns only. No prototype helper columns such as\n  source_files or period are added.\n\nUsage, in Step D after user review:\n    python3 scripts/prototype_08_master_qa_to_parquet.py\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport sys\nfrom dataclasses import dataclass\nfrom datetime import date, datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import Path\nfrom typing import Any\n\ntry:\n    import pyarrow as pa\n    import pyarrow.parquet as pq\n    from openpyxl import load_workbook\nexcept ImportError as e:\n    sys.exit(f"ERROR: {e}\\n  pip3 install pyarrow openpyxl --break-system-packages")\n\n\nETL_DIR = Path(__file__).resolve().parent / "etl"\nsys.path.insert(0, str(ETL_DIR))\nfrom storage import get_mi_master_path  # noqa: E402\n\n\nDEFAULT_INPUT_FILE = get_mi_master_path()\nDEFAULT_OUTPUT_FILE = Path("parquet/master_qa/master_qa.parquet")\nSOURCE_SHEET = "Q&A"\nHEADER_ROW = 2\nEXPECTED_ROW_COUNT = 13\n\nMASTER_QA_COLUMNS = (\n    "qa_id",\n    "strategic_market_id",\n    "question_text",\n    "answer_text",\n    "application_actions_json",\n    "source_remark",\n    "source_sheet",\n    "source_file_version",\n    "ingested_at",\n)\n\nEXPECTED_QA_IDS = tuple(f"qa_{index:04d}" for index in range(1, EXPECTED_ROW_COUNT + 1))\n\nMARKET_NAME_ALIASES = {\n    "공통": None,\n    "라베칸": "strategy_001",\n    "라베칸 라베칸듀오": "strategy_001",\n    "라베칸/라베칸듀오": "strategy_001",\n    "제이클": "strategy_002",\n    "가드렛 가드메트": "strategy_003",\n    "가드렛/가드메트": "strategy_003",\n    "타발리스": "strategy_004",\n    "시그마트": "strategy_005",\n    "리바로 리바로젯": "strategy_006",\n    "리바로/리바로젯": "strategy_006",\n    "리바로페노": "strategy_007",\n    "리바로하이": "strategy_008",\n    "리바로브이": "strategy_008",\n    "리바로하이 리바로브이": "strategy_008",\n    "트루패스": "strategy_009",\n    "피나스타/제이다트": "strategy_009",\n    "트루패스 피나스타 제이다트": "strategy_009",\n    "뉴트로진": "strategy_010",\n    "모빌리아": "strategy_010",\n    "뉴트로진 모빌리아": "strategy_010",\n    "악템라": "strategy_011",\n    "페린젝트": "strategy_012",\n    "베노훼럼": "strategy_012",\n    "페린젝트 베노훼럼": "strategy_012",\n    "헴리브라": "strategy_013",\n    "위너프/A+": "strategy_014",\n    "위너프 위너프A+": "strategy_014",\n    "엔커버": "strategy_015",\n    "플라주오피": "strategy_016",\n}\n\n\n@dataclass\nclass QALoadStats:\n    sheet_name: str = SOURCE_SHEET\n    raw_rows_scanned: int = 0\n    empty_rows: int = 0\n    staging_rows: int = 0\n\n\ndef utc_now_text() -> str:\n    return datetime.now(timezone.utc).replace(tzinfo=None).isoformat(sep=" ", timespec="seconds")\n\n\ndef normalize_header(value: object) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    return text or None\n\n\ndef to_jsonable(value: Any) -> Any:\n    if isinstance(value, (datetime, date)):\n        return value.isoformat()\n    if isinstance(value, Decimal):\n        return float(value)\n    return value\n\n\ndef dumps_json(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, default=to_jsonable, sort_keys=True)\n\n\ndef is_empty_row(values: list[Any] | tuple[Any, ...]) -> bool:\n    return all(value is None or str(value).strip() == "" for value in values)\n\n\ndef make_header_keys(headers: list[Any] | tuple[Any, ...]) -> list[str]:\n    seen: dict[str, int] = {}\n    keys: list[str] = []\n    for index, header in enumerate(headers, start=1):\n        normalized = normalize_header(header)\n        base = normalized if normalized is not None else f"__blank_col_{index}"\n        count = seen.get(base, 0) + 1\n        seen[base] = count\n        keys.append(base if count == 1 else f"{base}__{count}")\n    return keys\n\n\ndef build_raw_row_payload(\n    headers: list[Any] | tuple[Any, ...],\n    values: list[Any] | tuple[Any, ...],\n    source_row_id: int,\n) -> dict[str, Any]:\n    width = max(len(headers), len(values))\n    padded_headers = list(headers) + [None] * (width - len(headers))\n    padded_values = list(values) + [None] * (width - len(values))\n    keys = make_header_keys(padded_headers)\n    cells = []\n    values_by_header: dict[str, Any] = {}\n    for index, (header, key, value) in enumerate(zip(padded_headers, keys, padded_values), start=1):\n        json_value = to_jsonable(value)\n        cell = {\n            "column_index": index,\n            "header": normalize_header(header),\n            "header_key": key,\n            "value": json_value,\n        }\n        cells.append(cell)\n        values_by_header[key] = json_value\n    return {\n        "source_row_id": source_row_id,\n        "cells": cells,\n        "values_by_header": values_by_header,\n    }\n\n\ndef market_id_for_name(value: object) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    if not text:\n        return None\n    return MARKET_NAME_ALIASES.get(text)\n\n\ndef blank_record() -> dict[str, Any]:\n    return {column: None for column in MASTER_QA_COLUMNS}\n\n\ndef load_qa_records(\n    xlsx_path: Path,\n    ingested_at: str | None = None,\n) -> tuple[list[dict[str, Any]], QALoadStats]:\n    wb = load_workbook(xlsx_path, read_only=True, data_only=True)\n    try:\n        if SOURCE_SHEET not in wb.sheetnames:\n            # 260518 MI Master에는 Q&A 시트가 빠졌다. 이 단계의 역할은\n            # 원본 Q&A sheet를 parquet로 옮기는 것뿐이고, 수프렙/TIRZEPATIDE\n            # 같은 실제 override는 별도 override/config 경로에서 검증한다.\n            # 시트 부재를 fatal로 두면 run_layer0_postfix가 원본 변경 하나로\n            # 멈추므로, 빈 산출로 skip한다. 더미 Q&A를 생성하는 대안은 원본에\n            # 없는 데이터를 만든다는 점에서 기각했다.\n            return [], QALoadStats()\n\n        ws = wb[SOURCE_SHEET]\n        headers = list(\n            next(ws.iter_rows(min_row=HEADER_ROW, max_row=HEADER_ROW, values_only=True))\n        )\n        timestamp = ingested_at or utc_now_text()\n        stats = QALoadStats()\n        records: list[dict[str, Any]] = []\n        qa_index = 0\n\n        for source_row_id, values in enumerate(\n            ws.iter_rows(min_row=HEADER_ROW + 1, values_only=True),\n            start=HEADER_ROW + 1,\n        ):\n            stats.raw_rows_scanned += 1\n            if is_empty_row(values):\n                stats.empty_rows += 1\n                continue\n\n            qa_index += 1\n            raw_payload = build_raw_row_payload(headers, values, source_row_id=source_row_id)\n            question_type = values[1] if len(values) > 1 else None\n            market_name = values[2] if len(values) > 2 else None\n            question_text = values[3] if len(values) > 3 else None\n            answer_text = values[4] if len(values) > 4 else None\n            source_remark = values[5] if len(values) > 5 else None\n            actions = {\n                "question_type": question_type,\n                "market_name": market_name,\n                "raw_answer": answer_text,\n                "raw_marketing_note": source_remark,\n                "auto_apply_in_phase_2": False,\n                "raw_row": raw_payload,\n            }\n\n            record = blank_record()\n            record.update(\n                {\n                    "qa_id": f"qa_{qa_index:04d}",\n                    "strategic_market_id": market_id_for_name(market_name),\n                    "question_text": question_text,\n                    "answer_text": answer_text,\n                    "application_actions_json": dumps_json(actions),\n                    "source_remark": source_remark,\n                    "source_sheet": SOURCE_SHEET,\n                    "source_file_version": xlsx_path.name,\n                    "ingested_at": timestamp,\n                }\n            )\n            records.append(record)\n            stats.staging_rows += 1\n\n        return records, stats\n    finally:\n        wb.close()\n\n\ndef validate_records(records: list[dict[str, Any]]) -> None:\n    if not records:\n        return\n    if len(records) != EXPECTED_ROW_COUNT:\n        raise ValueError(f"master_qa row count must be {EXPECTED_ROW_COUNT}, found {len(records)}")\n\n    qa_ids = [record["qa_id"] for record in records]\n    if tuple(qa_ids) != EXPECTED_QA_IDS:\n        raise ValueError(f"qa_id sequence mismatch: expected={EXPECTED_QA_IDS}, actual={tuple(qa_ids)}")\n    if len(set(qa_ids)) != EXPECTED_ROW_COUNT:\n        raise ValueError(f"qa_id must be unique, found duplicates in {qa_ids}")\n\n    expected_columns = set(MASTER_QA_COLUMNS)\n    for index, record in enumerate(records, start=1):\n        extra_columns = sorted(set(record) - expected_columns)\n        missing_columns = sorted(expected_columns - set(record))\n        if extra_columns or missing_columns:\n            raise ValueError(\n                f"row {index} schema mismatch: extra={extra_columns}, missing={missing_columns}"\n            )\n\n        actions = json.loads(record["application_actions_json"])\n        expected_action_keys = {\n            "question_type",\n            "market_name",\n            "raw_answer",\n            "raw_marketing_note",\n            "auto_apply_in_phase_2",\n            "raw_row",\n        }\n        if set(actions) != expected_action_keys:\n            raise ValueError(\n                f"row {index} application_actions_json key mismatch: "\n                f"expected={sorted(expected_action_keys)}, actual={sorted(actions)}"\n            )\n        if actions["auto_apply_in_phase_2"] is not False:\n            raise ValueError(f"row {index} auto_apply_in_phase_2 must be false")\n        raw_row = actions["raw_row"]\n        if not isinstance(raw_row, dict) or "source_row_id" not in raw_row:\n            raise ValueError(f"row {index} raw_row payload is invalid")\n\n\ndef write_parquet(records: list[dict[str, Any]], output_file: Path) -> None:\n    output_file.parent.mkdir(parents=True, exist_ok=True)\n    schema = pa.schema([pa.field(column, pa.string()) for column in MASTER_QA_COLUMNS])\n    table = pa.Table.from_pylist(records, schema=schema)\n    pq.write_table(table, output_file, compression="zstd", compression_level=3)\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--input-file", default=str(DEFAULT_INPUT_FILE))\n    parser.add_argument("--output-file", default=str(DEFAULT_OUTPUT_FILE))\n    args = parser.parse_args()\n\n    input_file = Path(args.input_file)\n    output_file = Path(args.output_file)\n    if not input_file.exists():\n        sys.exit(f"ERROR: input file not found: {input_file}")\n\n    print("=" * 72)\n    print("MI Master Q&A -> Parquet")\n    print("=" * 72)\n    print(f"  input file:   {input_file}")\n    print(f"  source sheet: {SOURCE_SHEET}")\n    print(f"  output file:  {output_file}")\n    print(f"  columns:      {len(MASTER_QA_COLUMNS)} DDL columns")\n    print("  helpers:      none")\n\n    records, stats = load_qa_records(input_file)\n    validate_records(records)\n    write_parquet(records, output_file)\n\n    print("\\nResult")\n    print(f"  raw rows scanned: {stats.raw_rows_scanned}")\n    print(f"  empty rows:       {stats.empty_rows}")\n    print(f"  staging rows:     {stats.staging_rows}")\n    print(f"  unique qa_ids:    {len({row[\'qa_id\'] for row in records})}")\n    print(f"  output size:      {output_file.stat().st_size / 1024:.1f} KB")\n    print(f"  ingested_at:      {records[0][\'ingested_at\'] if records else None}")\n    print("\\nDone")\n\n\nif __name__ == "__main__":\n    main()\n'

_SOURCE_P09 = '"""\nprototype_09_master_brand_consolidation_to_parquet.py\n=====================================================\nMI Master 악템라 brand consolidation -> Parquet.\n\nPhase 09c policy:\n- Canonical row-generation logic:\n  /Users/rexxa/github/jw-market/etl/master_brand_consolidation.py\n- Canonical market-sheet scan logic:\n  /Users/rexxa/github/jw-market/etl/master_loader.py, limited to strategy_011\n- Canonical schema:\n  /Users/rexxa/github/jw-market/sql/schema_master.sql,\n  stg_master_brand_consolidation\n- Output schema is DDL columns only. No prototype helper columns such as\n  source_files or period are added.\n\nUsage, in Step D after user review:\n    python3 scripts/prototype_09_master_brand_consolidation_to_parquet.py\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any\n\ntry:\n    import pyarrow as pa\n    import pyarrow.parquet as pq\n    from openpyxl import load_workbook\nexcept ImportError as e:\n    sys.exit(f"ERROR: {e}\\n  pip3 install pyarrow openpyxl --break-system-packages")\n\ntry:\n    from strategic_exclusion_policy import classify_exclusion_cells as classify_exclusion_cells_by_policy\nexcept ModuleNotFoundError:\n    from pipeline.scripts.strategic_exclusion_policy import classify_exclusion_cells as classify_exclusion_cells_by_policy\n\n\nETL_DIR = Path(__file__).resolve().parent / "etl"\nsys.path.insert(0, str(ETL_DIR))\nfrom storage import get_mi_master_path  # noqa: E402\n\n\nDEFAULT_INPUT_FILE = get_mi_master_path()\nDEFAULT_OUTPUT_FILE = Path(\n    "parquet/master_brand_consolidation/master_brand_consolidation.parquet"\n)\n\nSTRATEGIC_MARKET_ID = "strategy_011"\nSOURCE_SHEET = "악템라"\nHEADER_ROW = 5\nPRODUCT_NAME_SOURCE_COLUMN = "PRODUCT NAME KOR"\n# 260518 악템라 시트는 Excel formatting tail이 길게 남아 raw scan 기준으로는\n# 995행까지 보이지만 실제 staging 대상은 26개 약품 행이다. 따라서 raw-scanned\n# exact count가 아니라 staging drug row, consolidation 6행, member index\n# uniqueness를 불변량으로 둔다. 빈 tail을 행으로 취급하는 대안은 무의미한\n# 공백 데이터를 catalog에 끌어들이므로 기각했다.\nEXPECTED_DRUG_ROWS = 26\nEXPECTED_ROW_COUNT = 6\nEXPECTED_MEMBER_DRUG_INDEXES = {5, 6, 18, 19, 22, 23}\nSOURCE_REMARK = "Master Remark indicates one-brand consolidation"\n\nMASTER_BRAND_CONSOLIDATION_COLUMNS = (\n    "strategic_market_id",\n    "brand_group",\n    "member_drug_index",\n    "member_drug_name",\n    "source_remark",\n    "source_sheet",\n    "source_file_version",\n    "ingested_at",\n)\n\nBRAND_GROUP_MEMBERS = {\n    "strategy_011": {\n        "엔브렐": {"엔브렐", "엔브렐마이클릭"},\n        "오렌시아": {"오렌시아", "오렌시아서브큐"},\n        "젤잔즈": {"젤잔즈", "젤잔즈엑스알"},\n    }\n}\n\nEXPECTED_BRAND_GROUP_COUNTS = {\n    "엔브렐": 2,\n    "오렌시아": 2,\n    "젤잔즈": 2,\n}\n\n\n@dataclass\nclass BrandConsolidationStats:\n    strategic_market_id: str = STRATEGIC_MARKET_ID\n    sheet_name: str = SOURCE_SHEET\n    header_row: int = HEADER_ROW\n    raw_rows_scanned: int = 0\n    empty_rows: int = 0\n    excluded_rows: int = 0\n    staging_drug_rows: int = 0\n    brand_consolidation_rows: int = 0\n\n\ndef utc_now_text() -> str:\n    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")\n\n\ndef is_empty_row(values: list[Any] | tuple[Any, ...]) -> bool:\n    return all(value is None or str(value).strip() == "" for value in values)\n\n\ndef _is_class_header(header: Any) -> bool:\n    text = str(header or "").strip().lower()\n    normalized = "".join(ch for ch in text if ch.isalnum())\n    return normalized in {"class", "class1", "class2"} or normalized.startswith("class")\n\n\ndef is_excluded_row(\n    values: list[Any] | tuple[Any, ...],\n    headers: list[Any] | tuple[Any, ...] | None = None,\n    *,\n    strategic_market_id: str | None = STRATEGIC_MARKET_ID,\n    sheet_name: str | None = SOURCE_SHEET,\n) -> bool:\n    class_indexes = {idx for idx, header in enumerate(headers or []) if _is_class_header(header)}\n    row_excluded, _class_excluded = classify_exclusion_cells_by_policy(\n        values,\n        class_indexes=class_indexes,\n        strategic_market_id=strategic_market_id,\n        sheet_name=sheet_name,\n    )\n    return row_excluded\n\n\ndef header_index(headers: list[Any], source_column: str) -> int:\n    present_headers = {str(header).strip(): index for index, header in enumerate(headers) if header}\n    if source_column not in present_headers:\n        raise ValueError(f"required source column not found: {source_column}")\n    return present_headers[source_column]\n\n\ndef build_brand_consolidation_rows(\n    strategic_market_id: str,\n    drug_record: dict[str, Any],\n    ingested_at: str,\n) -> list[dict[str, Any]]:\n    groups = BRAND_GROUP_MEMBERS.get(strategic_market_id, {})\n    product_name = drug_record.get("product_name")\n    if product_name is None:\n        return []\n    product_text = str(product_name).strip()\n    rows: list[dict[str, Any]] = []\n    for brand_group, members in groups.items():\n        if product_text in members:\n            rows.append(\n                {\n                    "strategic_market_id": strategic_market_id,\n                    "brand_group": brand_group,\n                    "member_drug_index": drug_record["drug_index"],\n                    "member_drug_name": product_text,\n                    "source_remark": SOURCE_REMARK,\n                    "source_sheet": drug_record["source_sheet"],\n                    "source_file_version": drug_record["source_file_version"],\n                    "ingested_at": ingested_at,\n                }\n            )\n    return rows\n\n\ndef load_brand_consolidation_records(\n    xlsx_path: Path,\n    ingested_at: str | None = None,\n) -> tuple[list[dict[str, Any]], BrandConsolidationStats]:\n    wb = load_workbook(xlsx_path, read_only=True, data_only=True)\n    try:\n        if SOURCE_SHEET not in wb.sheetnames:\n            raise ValueError(f"required sheet not found: {SOURCE_SHEET!r}; sheets={wb.sheetnames}")\n\n        ws = wb[SOURCE_SHEET]\n        headers = list(\n            next(ws.iter_rows(min_row=HEADER_ROW, max_row=HEADER_ROW, values_only=True))\n        )\n        product_idx = header_index(headers, PRODUCT_NAME_SOURCE_COLUMN)\n        timestamp = ingested_at or utc_now_text()\n        stats = BrandConsolidationStats()\n        records: list[dict[str, Any]] = []\n        drug_index = 0\n\n        for source_row_id, values in enumerate(\n            ws.iter_rows(min_row=HEADER_ROW + 1, values_only=True),\n            start=HEADER_ROW + 1,\n        ):\n            stats.raw_rows_scanned += 1\n            if is_empty_row(values):\n                stats.empty_rows += 1\n                continue\n            if is_excluded_row(values, headers=headers):\n                stats.excluded_rows += 1\n                continue\n\n            drug_index += 1\n            stats.staging_drug_rows += 1\n            drug_record = {\n                "strategic_market_id": STRATEGIC_MARKET_ID,\n                "drug_index": drug_index,\n                "product_name": values[product_idx] if len(values) > product_idx else None,\n                "source_sheet": SOURCE_SHEET,\n                "source_file_version": xlsx_path.name,\n                "source_row_id": source_row_id,\n                "ingested_at": timestamp,\n            }\n            brand_rows = build_brand_consolidation_rows(\n                STRATEGIC_MARKET_ID,\n                drug_record,\n                timestamp,\n            )\n            records.extend(brand_rows)\n            stats.brand_consolidation_rows += len(brand_rows)\n\n        return records, stats\n    finally:\n        wb.close()\n\n\ndef validate_records(records: list[dict[str, Any]], stats: BrandConsolidationStats) -> None:\n    if stats.staging_drug_rows != EXPECTED_DRUG_ROWS:\n        raise ValueError(\n            f"staging drug rows must be {EXPECTED_DRUG_ROWS}, found {stats.staging_drug_rows}"\n        )\n    if len(records) != EXPECTED_ROW_COUNT:\n        raise ValueError(\n            f"brand consolidation row count must be {EXPECTED_ROW_COUNT}, found {len(records)}"\n        )\n\n    pk_values = [\n        (record["strategic_market_id"], record["brand_group"], record["member_drug_index"])\n        for record in records\n    ]\n    if len(set(pk_values)) != EXPECTED_ROW_COUNT:\n        raise ValueError(f"compound PK must be unique, found duplicates in {pk_values}")\n\n    member_indexes = {int(record["member_drug_index"]) for record in records}\n    if member_indexes != EXPECTED_MEMBER_DRUG_INDEXES:\n        raise ValueError(\n            f"member_drug_index mismatch: "\n            f"expected={sorted(EXPECTED_MEMBER_DRUG_INDEXES)}, actual={sorted(member_indexes)}"\n        )\n\n    group_counts: dict[str, int] = {}\n    for record in records:\n        group_counts[record["brand_group"]] = group_counts.get(record["brand_group"], 0) + 1\n    if group_counts != EXPECTED_BRAND_GROUP_COUNTS:\n        raise ValueError(\n            f"brand_group distribution mismatch: "\n            f"expected={EXPECTED_BRAND_GROUP_COUNTS}, actual={group_counts}"\n        )\n\n    expected_columns = set(MASTER_BRAND_CONSOLIDATION_COLUMNS)\n    for index, record in enumerate(records, start=1):\n        extra_columns = sorted(set(record) - expected_columns)\n        missing_columns = sorted(expected_columns - set(record))\n        if extra_columns or missing_columns:\n            raise ValueError(\n                f"row {index} schema mismatch: extra={extra_columns}, missing={missing_columns}"\n            )\n        if record["strategic_market_id"] != STRATEGIC_MARKET_ID:\n            raise ValueError(f"row {index} strategic_market_id mismatch: {record}")\n        if record["source_sheet"] != SOURCE_SHEET:\n            raise ValueError(f"row {index} source_sheet mismatch: {record}")\n        if record["source_remark"] != SOURCE_REMARK:\n            raise ValueError(f"row {index} source_remark mismatch: {record}")\n\n\ndef write_parquet(records: list[dict[str, Any]], output_file: Path) -> None:\n    output_file.parent.mkdir(parents=True, exist_ok=True)\n    schema = pa.schema([pa.field(column, pa.string()) for column in MASTER_BRAND_CONSOLIDATION_COLUMNS])\n    rows = [\n        {column: None if record[column] is None else str(record[column]) for column in MASTER_BRAND_CONSOLIDATION_COLUMNS}\n        for record in records\n    ]\n    table = pa.Table.from_pylist(rows, schema=schema)\n    pq.write_table(table, output_file, compression="zstd", compression_level=3)\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--input-file", default=str(DEFAULT_INPUT_FILE))\n    parser.add_argument("--output-file", default=str(DEFAULT_OUTPUT_FILE))\n    args = parser.parse_args()\n\n    input_file = Path(args.input_file)\n    output_file = Path(args.output_file)\n    if not input_file.exists():\n        sys.exit(f"ERROR: input file not found: {input_file}")\n\n    print("=" * 72)\n    print("MI Master brand_consolidation -> Parquet")\n    print("=" * 72)\n    print(f"  input file:   {input_file}")\n    print(f"  source sheet: {SOURCE_SHEET}")\n    print(f"  output file:  {output_file}")\n    print(f"  columns:      {len(MASTER_BRAND_CONSOLIDATION_COLUMNS)} DDL columns")\n    print("  helpers:      none")\n\n    records, stats = load_brand_consolidation_records(input_file)\n    validate_records(records, stats)\n    write_parquet(records, output_file)\n\n    print("\\nResult")\n    print(f"  raw rows scanned:             {stats.raw_rows_scanned}")\n    print(f"  empty rows:                   {stats.empty_rows}")\n    print(f"  excluded rows:                {stats.excluded_rows}")\n    print(f"  staging drug rows:            {stats.staging_drug_rows}")\n    print(f"  brand consolidation rows:     {stats.brand_consolidation_rows}")\n    print(f"  compound PK unique:           {len(records)}")\n    print(f"  output size:                  {output_file.stat().st_size / 1024:.1f} KB")\n    print(f"  ingested_at:                  {records[0][\'ingested_at\'] if records else None}")\n    print("\\nDone")\n\n\nif __name__ == "__main__":\n    main()\n'

_SOURCE_P10 = '"""\nprototype_10_master_mapping_table_to_parquet.py\n================================================\nMI Master manual mapping table -> Parquet.\n\nPhase 09d policy:\n- Canonical row-generation logic:\n  /Users/rexxa/github/jw-market/etl/master_loader.py::_manual_mapping_records\n- Canonical market-sheet scan / mapping helpers:\n  /Users/rexxa/github/jw-market/etl/master_loader.py and\n  /Users/rexxa/github/jw-market/etl/master_transform.py\n- Canonical schema:\n  /Users/rexxa/github/jw-market/sql/schema_master.sql,\n  stg_master_mapping_table\n- Output schema is DDL columns only. No prototype helper columns such as\n  source_files or period are added.\n\nUsage, in Step D after user review:\n    python3 scripts/prototype_10_master_mapping_table_to_parquet.py\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport re\nimport sys\nfrom dataclasses import dataclass\nfrom datetime import date, datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import Path\nfrom typing import Any\n\ntry:\n    import pyarrow as pa\n    import pyarrow.parquet as pq\n    from openpyxl import load_workbook\nexcept ImportError as e:\n    sys.exit(f"ERROR: {e}\\n  pip3 install pyarrow openpyxl --break-system-packages")\n\n\nETL_DIR = Path(__file__).resolve().parent / "etl"\nsys.path.insert(0, str(ETL_DIR))\nfrom storage import get_mi_master_path  # noqa: E402\n\n\nDEFAULT_INPUT_FILE = get_mi_master_path()\nMASTER_ROOT = DEFAULT_INPUT_FILE.parent\nDEFAULT_CATALOG_PATH = Path("docs/reference/master_column_mapping_catalog.md")\nDEFAULT_OUTPUT_FILE = Path("parquet/master_mapping_table/master_mapping_table.parquet")\n\nSTANDARD_PREFIX = "drug_extra_json."\n# 4/22 기준 5932행에서 260518 기준 5956행으로 24행이 늘었다.\n# diff 확인 결과 시장정의/Target 계열의 정상 추가분이라, 검증을 완화하지 않고\n# 새 원본 버전에 맞춘 strict count로 고정한다. 행수 검사를 제거하는 대안은\n# mapping 누락을 조기에 잡지 못하므로 기각했다.\nEXPECTED_ROW_COUNT = 5956\nZERO_MAPPING_MARKETS = {"strategy_006", "strategy_007", "strategy_009"}\n\nMASTER_MAPPING_TABLE_COLUMNS = (\n    "mapping_id",\n    "strategic_market_id",\n    "source_value",\n    "target_column",\n    "target_value",\n    "mapping_type",\n    "source_sheet",\n    "source_file_version",\n    "ingested_at",\n)\n\n\n@dataclass(frozen=True)\nclass MarketSheetConfig:\n    strategic_market_id: str\n    sheet_name: str\n    header_row: int\n    source_type: str\n\n\nMARKET_SHEETS: tuple[MarketSheetConfig, ...] = (\n    MarketSheetConfig("strategy_001", "라베칸 라베칸듀오", 5, "UBIST"),\n    MarketSheetConfig("strategy_002", "제이클", 5, "IQVIA"),\n    MarketSheetConfig("strategy_003", "가드렛 가드메트", 5, "IQVIA"),\n    MarketSheetConfig("strategy_004", "타발리스", 5, "IQVIA"),\n    MarketSheetConfig("strategy_005", "시그마트", 5, "UBIST"),\n    MarketSheetConfig("strategy_006", "리바로 리바로젯", 4, "UBIST"),\n    MarketSheetConfig("strategy_007", "리바로페노", 4, "UBIST"),\n    MarketSheetConfig("strategy_008", "리바로하이 리바로브이", 5, "UBIST"),\n    MarketSheetConfig("strategy_009", "트루패스 피나스타 제이다트", 5, "UBIST"),\n    MarketSheetConfig("strategy_010", "뉴트로진 모빌리아", 5, "IQVIA"),\n    MarketSheetConfig("strategy_011", "악템라", 5, "IQVIA"),\n    MarketSheetConfig("strategy_012", "페린젝트 베노훼럼", 5, "IQVIA"),\n    MarketSheetConfig("strategy_013", "헴리브라", 5, "IQVIA"),\n    MarketSheetConfig("strategy_014", "위너프 위너프A+", 5, "IQVIA"),\n    MarketSheetConfig("strategy_015", "엔커버", 7, "IQVIA"),\n    MarketSheetConfig("strategy_016", "플라주오피", 5, "IQVIA"),\n)\n\nEXPECTED_MARKET_STATS = {\n    "strategy_001": {\n        "sheet_name": "라베칸 라베칸듀오",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 637,\n        "excluded_rows": 0,\n        "staging_rows": 358,\n        "manual_specs": 3,\n        "mapping_rows": 716,\n    },\n    "strategy_002": {\n        "sheet_name": "제이클",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 950,\n        "excluded_rows": 0,\n        "staging_rows": 45,\n        "manual_specs": 3,\n        "mapping_rows": 135,\n    },\n    "strategy_003": {\n        "sheet_name": "가드렛 가드메트",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 913,\n        "excluded_rows": 0,\n        "staging_rows": 82,\n        "manual_specs": 2,\n        "mapping_rows": 164,\n    },\n    "strategy_004": {\n        "sheet_name": "타발리스",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 985,\n        "excluded_rows": 0,\n        "staging_rows": 10,\n        "manual_specs": 1,\n        "mapping_rows": 9,\n    },\n    "strategy_005": {\n        "sheet_name": "시그마트",\n        "header_row": 5,\n        "raw_rows_scanned": 294,\n        "empty_rows": 0,\n        "excluded_rows": 0,\n        "staging_rows": 294,\n        "manual_specs": 4,\n        "mapping_rows": 1176,\n    },\n    "strategy_006": {\n        "sheet_name": "리바로 리바로젯",\n        "header_row": 4,\n        "raw_rows_scanned": 1295,\n        "empty_rows": 200,\n        "excluded_rows": 48,\n        "staging_rows": 1047,\n        "manual_specs": 0,\n        "mapping_rows": 0,\n    },\n    "strategy_007": {\n        "sheet_name": "리바로페노",\n        "header_row": 4,\n        "raw_rows_scanned": 996,\n        "empty_rows": 385,\n        "excluded_rows": 494,\n        "staging_rows": 117,\n        "manual_specs": 0,\n        "mapping_rows": 0,\n    },\n    "strategy_008": {\n        "sheet_name": "리바로하이 리바로브이",\n        "header_row": 5,\n        "raw_rows_scanned": 1096,\n        "empty_rows": 15,\n        "excluded_rows": 0,\n        "staging_rows": 1081,\n        "manual_specs": 5,\n        "mapping_rows": 1676,\n    },\n    "strategy_009": {\n        "sheet_name": "트루패스 피나스타 제이다트",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 589,\n        "excluded_rows": 1,\n        "staging_rows": 405,\n        "manual_specs": 0,\n        "mapping_rows": 0,\n    },\n    "strategy_010": {\n        "sheet_name": "뉴트로진 모빌리아",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 985,\n        "excluded_rows": 0,\n        "staging_rows": 10,\n        "manual_specs": 4,\n        "mapping_rows": 38,\n    },\n    "strategy_011": {\n        "sheet_name": "악템라",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 969,\n        "excluded_rows": 0,\n        "staging_rows": 26,\n        "manual_specs": 3,\n        "mapping_rows": 78,\n    },\n    "strategy_012": {\n        "sheet_name": "페린젝트 베노훼럼",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 919,\n        "excluded_rows": 0,\n        "staging_rows": 76,\n        "manual_specs": 5,\n        "mapping_rows": 198,\n    },\n    "strategy_013": {\n        "sheet_name": "헴리브라",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 981,\n        "excluded_rows": 1,\n        "staging_rows": 13,\n        "manual_specs": 2,\n        "mapping_rows": 26,\n    },\n    "strategy_014": {\n        "sheet_name": "위너프 위너프A+",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 664,\n        "excluded_rows": 8,\n        "staging_rows": 323,\n        "manual_specs": 6,\n        "mapping_rows": 1696,\n    },\n    "strategy_015": {\n        "sheet_name": "엔커버",\n        "header_row": 7,\n        "raw_rows_scanned": 993,\n        "empty_rows": 989,\n        "excluded_rows": 0,\n        "staging_rows": 4,\n        "manual_specs": 1,\n        "mapping_rows": 4,\n    },\n    "strategy_016": {\n        "sheet_name": "플라주오피",\n        "header_row": 5,\n        "raw_rows_scanned": 995,\n        "empty_rows": 943,\n        "excluded_rows": 31,\n        "staging_rows": 21,\n        "manual_specs": 2,\n        "mapping_rows": 40,\n    },\n}\n\nEXPECTED_MARKET_DISTRIBUTION = {\n    "strategy_001": 716,\n    "strategy_002": 135,\n    "strategy_003": 164,\n    "strategy_004": 9,\n    "strategy_005": 1176,\n    "strategy_008": 1676,\n    "strategy_010": 38,\n    "strategy_011": 78,\n    "strategy_012": 198,\n    "strategy_013": 26,\n    "strategy_014": 1696,\n    "strategy_015": 4,\n    "strategy_016": 40,\n}\n\nEXPECTED_MAPPING_TYPE_DISTRIBUTION = {\n    "class_recode": 1376,\n    "manual_mapping": 2009,\n    "molecule_recode": 1984,\n    "nhi_overlay": 490,\n    "strength_recode": 97,\n}\n\n\n@dataclass\nclass MarketMappingStats:\n    strategic_market_id: str\n    sheet_name: str\n    header_row: int\n    max_row: int\n    max_col: int\n    raw_rows_scanned: int = 0\n    empty_rows: int = 0\n    excluded_rows: int = 0\n    staging_rows: int = 0\n    manual_specs: int = 0\n    mapping_rows: int = 0\n\n\ndef utc_now_text() -> str:\n    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")\n\n\ndef resolve_input_file(path: Path) -> Path:\n    if path.exists():\n        return path\n    candidates = sorted(file for file in MASTER_ROOT.glob("*.xlsx") if not file.name.startswith("~$"))\n    if not candidates:\n        raise FileNotFoundError(f"No Master xlsx found under {MASTER_ROOT}")\n    return candidates[-1]\n\n\ndef normalize_header(value: object) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    return text or None\n\n\ndef to_jsonable(value: Any) -> Any:\n    if isinstance(value, (datetime, date)):\n        return value.isoformat()\n    if isinstance(value, Decimal):\n        return float(value)\n    return value\n\n\ndef is_empty_row(values: list[Any] | tuple[Any, ...]) -> bool:\n    return all(value is None or str(value).strip() == "" for value in values)\n\n\ndef is_excluded_row(values: list[Any] | tuple[Any, ...]) -> bool:\n    for value in values:\n        if value is None:\n            continue\n        text = str(value).strip()\n        if "제외" in text and not text.startswith("비제외"):\n            return True\n    return False\n\n\ndef _header_lookup(headers: list[Any] | tuple[Any, ...], values: list[Any] | tuple[Any, ...]) -> dict[str, Any]:\n    lookup: dict[str, Any] = {}\n    for header, value in zip(headers, values):\n        normalized = normalize_header(header)\n        if normalized is not None and normalized not in lookup:\n            lookup[normalized] = value\n    return lookup\n\n\ndef _lookup_source_value(lookup: dict[str, Any], source_column: str | None) -> Any:\n    if source_column is None:\n        return None\n    if source_column in lookup:\n        return lookup[source_column]\n    for header, value in lookup.items():\n        if header.startswith(source_column):\n            return value\n    return None\n\n\ndef _position_value(values: list[Any] | tuple[Any, ...], column_index: int) -> Any:\n    if column_index <= 0 or column_index > len(values):\n        return None\n    return values[column_index - 1]\n\n\ndef _lookup_key(*values: Any) -> tuple[str, ...] | None:\n    key: list[str] = []\n    for value in values:\n        if value is None:\n            return None\n        text = str(value).strip()\n        if not text:\n            return None\n        key.append(text)\n    return tuple(key)\n\n\ndef _single_lookup_key(value: Any) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    return text or None\n\n\ndef explicit_lookup_join(data_rows: list[tuple[int, tuple[Any, ...]]]) -> dict[int, dict[str, Any]]:\n    """Return strategy_008 lookup-derived standard column overwrites."""\n    lookup1: dict[tuple[str, str], dict[str, Any]] = {}\n    for _, values in data_rows:\n        key = _lookup_key(_position_value(values, 17), _position_value(values, 18))\n        if key and key not in lookup1:\n            lookup1[key] = {\n                "molecule": _position_value(values, 19),\n                "molecule_disease_definition": _position_value(values, 20),\n                "composition_type": _position_value(values, 21),\n                "class": _position_value(values, 22),\n            }\n\n    lookup2: dict[str, Any] = {}\n    for _, values in data_rows:\n        key = _single_lookup_key(_position_value(values, 25))\n        if key and key not in lookup2:\n            lookup2[key] = _position_value(values, 26)\n\n    overrides: dict[int, dict[str, Any]] = {}\n    for source_row_id, values in data_rows:\n        left_key = _lookup_key(_position_value(values, 2), _position_value(values, 3))\n        if not left_key or left_key not in lookup1:\n            continue\n        row_override = dict(lookup1[left_key])\n        molecule_key = _single_lookup_key(row_override.get("molecule"))\n        row_override["class_2"] = lookup2.get(molecule_key) if molecule_key else None\n        overrides[source_row_id] = row_override\n    return overrides\n\n\ndef _extra_key(metadata_key: str) -> str:\n    return metadata_key[len(STANDARD_PREFIX) :]\n\n\ndef apply_column_mapping(\n    headers: list[Any] | tuple[Any, ...],\n    values: list[Any] | tuple[Any, ...],\n    metadata: dict[str, dict[str, Any]],\n) -> tuple[dict[str, Any], dict[str, Any]]:\n    lookup = _header_lookup(headers, values)\n    standard: dict[str, Any] = {}\n    extras: dict[str, Any] = {}\n    for target_column, spec in metadata.items():\n        source_column = normalize_header(spec.get("source_column"))\n        value = _lookup_source_value(lookup, source_column)\n        if target_column.startswith(STANDARD_PREFIX):\n            extras[_extra_key(target_column)] = to_jsonable(value)\n        else:\n            standard[target_column] = value\n    return standard, extras\n\n\ndef load_column_metadata_catalog(path: Path) -> dict[str, dict[str, dict[str, Any]]]:\n    text = path.read_text(encoding="utf-8")\n    catalog: dict[str, dict[str, dict[str, Any]]] = {}\n    current_market: str | None = None\n    lines = iter(text.splitlines())\n    for line in lines:\n        heading = re.match(r"^###\\s+(strategy_\\d{3})\\s+—", line)\n        if heading:\n            current_market = heading.group(1)\n            continue\n        if current_market and line.strip() == "```json":\n            block: list[str] = []\n            for json_line in lines:\n                if json_line.strip() == "```":\n                    break\n                block.append(json_line)\n            catalog[current_market] = json.loads("\\n".join(block))\n            current_market = None\n    missing = sorted({config.strategic_market_id for config in MARKET_SHEETS} - set(catalog))\n    if missing:\n        raise ValueError(f"column metadata catalog missing markets: {missing}")\n    return catalog\n\n\ndef make_mapping_id(\n    strategic_market_id: str,\n    source_column: object,\n    source_value: object,\n    target_column: object,\n    target_value: object,\n    source_row_id: int | None = None,\n) -> str:\n    parts = [\n        strategic_market_id,\n        str(source_row_id or ""),\n        str(source_column or ""),\n        str(source_value or ""),\n        str(target_column or ""),\n        str(target_value or ""),\n    ]\n    digest = hashlib.sha256("|".join(parts).encode("utf-8")).hexdigest()[:16]\n    return f"{strategic_market_id}:{digest}"\n\n\ndef mapping_type_for(target_column: str, source_column: object) -> str:\n    lowered = f"{target_column} {source_column or \'\'}".lower()\n    if "molecule" in lowered or "성분" in lowered:\n        return "molecule_recode"\n    if "class" in lowered:\n        return "class_recode"\n    if "strength" in lowered or "규격" in lowered:\n        return "strength_recode"\n    if "nhi" in lowered or "급여" in lowered:\n        return "nhi_overlay"\n    return "manual_mapping"\n\n\ndef raw_value_for_mapping(\n    headers: list[Any] | tuple[Any, ...],\n    values: list[Any] | tuple[Any, ...],\n    spec: dict[str, Any],\n) -> Any:\n    lookup = _header_lookup(headers, values)\n    overlay_target = normalize_header(spec.get("overlay_target"))\n    source_column = normalize_header(spec.get("source_column"))\n    if overlay_target and overlay_target in lookup:\n        return lookup.get(overlay_target)\n    return _lookup_source_value(lookup, source_column)\n\n\ndef _headers_from_sheet(ws: Any, header_row: int) -> list[Any]:\n    return list(next(ws.iter_rows(min_row=header_row, max_row=header_row, values_only=True)))\n\n\ndef _manual_mapping_records(\n    strategic_market_id: str,\n    source_sheet: str,\n    source_file_version: str,\n    source_row_id: int,\n    headers: list[Any],\n    values: tuple[Any, ...],\n    metadata: dict[str, dict[str, Any]],\n    standard_values: dict[str, Any],\n    extras: dict[str, Any],\n    ingested_at: str,\n    inclusion_standard_values: dict[str, Any] | None = None,\n    inclusion_extras: dict[str, Any] | None = None,\n) -> list[dict[str, Any]]:\n    records: list[dict[str, Any]] = []\n    inclusion_standard_values = inclusion_standard_values or standard_values\n    inclusion_extras = inclusion_extras or extras\n    for target_column, spec in metadata.items():\n        metadata_type = str(spec.get("type") or "")\n        if not metadata_type.startswith("manual"):\n            continue\n        source_column = spec.get("source_column")\n        if target_column.startswith("drug_extra_json."):\n            extra_key = target_column.split(".", 1)[1]\n            target_value = extras.get(extra_key)\n            inclusion_target_value = inclusion_extras.get(extra_key)\n        else:\n            target_value = standard_values.get(target_column)\n            inclusion_target_value = inclusion_standard_values.get(target_column)\n        source_value = raw_value_for_mapping(headers, values, spec)\n        if source_value is None and inclusion_target_value is None:\n            continue\n        records.append(\n            {\n                "mapping_id": make_mapping_id(\n                    strategic_market_id,\n                    source_column,\n                    source_value,\n                    target_column,\n                    target_value,\n                    source_row_id=source_row_id,\n                ),\n                "strategic_market_id": strategic_market_id,\n                "source_value": None if source_value is None else str(source_value),\n                "target_column": target_column,\n                "target_value": None if target_value is None else str(target_value),\n                "mapping_type": mapping_type_for(target_column, source_column),\n                "source_sheet": source_sheet,\n                "source_file_version": source_file_version,\n                "ingested_at": ingested_at,\n            }\n        )\n    return records\n\n\ndef load_mapping_records(\n    xlsx_path: Path,\n    catalog_path: Path,\n    ingested_at: str | None = None,\n) -> tuple[list[dict[str, Any]], list[MarketMappingStats]]:\n    metadata_catalog = load_column_metadata_catalog(catalog_path)\n    timestamp = ingested_at or utc_now_text()\n    records: list[dict[str, Any]] = []\n    stats: list[MarketMappingStats] = []\n\n    wb = load_workbook(xlsx_path, read_only=True, data_only=True)\n    try:\n        for config in MARKET_SHEETS:\n            if config.sheet_name not in wb.sheetnames:\n                raise ValueError(f"required sheet not found: {config.sheet_name!r}; sheets={wb.sheetnames}")\n            ws = wb[config.sheet_name]\n            headers = _headers_from_sheet(ws, config.header_row)\n            metadata = metadata_catalog[config.strategic_market_id]\n            manual_specs = sum(\n                1 for spec in metadata.values() if str(spec.get("type") or "").startswith("manual")\n            )\n            market_stats = MarketMappingStats(\n                strategic_market_id=config.strategic_market_id,\n                sheet_name=config.sheet_name,\n                header_row=config.header_row,\n                max_row=ws.max_row,\n                max_col=ws.max_column,\n                manual_specs=manual_specs,\n            )\n\n            row_items = list(\n                enumerate(\n                    ws.iter_rows(min_row=config.header_row + 1, values_only=True),\n                    start=config.header_row + 1,\n                )\n            )\n            explicit_overrides = (\n                explicit_lookup_join(row_items) if config.strategic_market_id == "strategy_008" else {}\n            )\n\n            for source_row_id, values in row_items:\n                market_stats.raw_rows_scanned += 1\n                if is_empty_row(values):\n                    market_stats.empty_rows += 1\n                    continue\n                if is_excluded_row(values):\n                    market_stats.excluded_rows += 1\n                    continue\n\n                market_stats.staging_rows += 1\n                standard_values, extras = apply_column_mapping(headers, values, metadata)\n                inclusion_standard_values = standard_values\n                if source_row_id in explicit_overrides:\n                    standard_values = dict(standard_values)\n                    standard_values.update(explicit_overrides[source_row_id])\n                mapping_rows = _manual_mapping_records(\n                    config.strategic_market_id,\n                    config.sheet_name,\n                    xlsx_path.name,\n                    source_row_id,\n                    headers,\n                    values,\n                    metadata,\n                    standard_values,\n                    extras,\n                    timestamp,\n                    inclusion_standard_values=inclusion_standard_values,\n                )\n                records.extend(mapping_rows)\n                market_stats.mapping_rows += len(mapping_rows)\n\n            stats.append(market_stats)\n    finally:\n        wb.close()\n\n    return records, stats\n\n\ndef _count_by(records: list[dict[str, Any]], key: str) -> dict[str, int]:\n    counts: dict[str, int] = {}\n    for record in records:\n        value = str(record.get(key) or "")\n        counts[value] = counts.get(value, 0) + 1\n    return counts\n\n\ndef validate_records(records: list[dict[str, Any]], stats: list[MarketMappingStats]) -> None:\n    if len(records) != EXPECTED_ROW_COUNT:\n        raise ValueError(f"mapping row count must be {EXPECTED_ROW_COUNT}, found {len(records)}")\n\n    mapping_ids = [record["mapping_id"] for record in records]\n    if len(set(mapping_ids)) != EXPECTED_ROW_COUNT:\n        duplicates = sorted({value for value in mapping_ids if mapping_ids.count(value) > 1})\n        raise ValueError(f"mapping_id must be unique, duplicate examples={duplicates[:10]}")\n\n    stats_by_market = {item.strategic_market_id: item for item in stats}\n    expected_market_ids = {config.strategic_market_id for config in MARKET_SHEETS}\n    if set(stats_by_market) != expected_market_ids:\n        raise ValueError(\n            f"market stats mismatch: expected={sorted(expected_market_ids)}, actual={sorted(stats_by_market)}"\n        )\n\n    for market_id, expected in EXPECTED_MARKET_STATS.items():\n        actual = stats_by_market[market_id]\n        for field in (\n            "sheet_name",\n            "header_row",\n            "raw_rows_scanned",\n            "empty_rows",\n            "excluded_rows",\n            "staging_rows",\n            "manual_specs",\n            "mapping_rows",\n        ):\n            actual_value = getattr(actual, field)\n            expected_value = expected[field]\n            if actual_value != expected_value:\n                raise ValueError(\n                    f"{market_id} {field} mismatch: expected={expected_value}, actual={actual_value}"\n                )\n\n    zero_mapping_actual = {item.strategic_market_id for item in stats if item.mapping_rows == 0}\n    if zero_mapping_actual != ZERO_MAPPING_MARKETS:\n        raise ValueError(\n            f"zero mapping market mismatch: expected={sorted(ZERO_MAPPING_MARKETS)}, "\n            f"actual={sorted(zero_mapping_actual)}"\n        )\n\n    market_distribution = _count_by(records, "strategic_market_id")\n    if market_distribution != EXPECTED_MARKET_DISTRIBUTION:\n        raise ValueError(\n            f"market distribution mismatch: expected={EXPECTED_MARKET_DISTRIBUTION}, "\n            f"actual={market_distribution}"\n        )\n\n    type_distribution = _count_by(records, "mapping_type")\n    if type_distribution != EXPECTED_MAPPING_TYPE_DISTRIBUTION:\n        raise ValueError(\n            f"mapping_type distribution mismatch: expected={EXPECTED_MAPPING_TYPE_DISTRIBUTION}, "\n            f"actual={type_distribution}"\n        )\n\n    expected_columns = set(MASTER_MAPPING_TABLE_COLUMNS)\n    for index, record in enumerate(records, start=1):\n        extra_columns = sorted(set(record) - expected_columns)\n        missing_columns = sorted(expected_columns - set(record))\n        if extra_columns or missing_columns:\n            raise ValueError(\n                f"row {index} schema mismatch: extra={extra_columns}, missing={missing_columns}"\n            )\n        if not record["mapping_id"]:\n            raise ValueError(f"row {index} has blank mapping_id")\n        if not record["target_column"]:\n            raise ValueError(f"row {index} has blank target_column: {record}")\n        if record["mapping_type"] not in EXPECTED_MAPPING_TYPE_DISTRIBUTION:\n            raise ValueError(f"row {index} unexpected mapping_type: {record[\'mapping_type\']}")\n\n\ndef write_parquet(records: list[dict[str, Any]], output_file: Path) -> None:\n    output_file.parent.mkdir(parents=True, exist_ok=True)\n    schema = pa.schema([pa.field(column, pa.string()) for column in MASTER_MAPPING_TABLE_COLUMNS])\n    rows = [\n        {column: None if record[column] is None else str(record[column]) for column in MASTER_MAPPING_TABLE_COLUMNS}\n        for record in records\n    ]\n    table = pa.Table.from_pylist(rows, schema=schema)\n    pq.write_table(table, output_file, compression="zstd")\n\n\ndef print_summary(\n    records: list[dict[str, Any]],\n    stats: list[MarketMappingStats],\n    output_file: Path,\n) -> None:\n    print("Phase 09d master_mapping_table load")\n    print(f"mapping_rows: {len(records)}")\n    print(f"unique_mapping_id: {len({record[\'mapping_id\'] for record in records})}")\n    print(f"mapping_type_distribution: {_count_by(records, \'mapping_type\')}")\n    print("market_distribution:")\n    for item in stats:\n        print(\n            f"  {item.strategic_market_id} {item.sheet_name}: "\n            f"raw={item.raw_rows_scanned}, empty={item.empty_rows}, "\n            f"excluded={item.excluded_rows}, staging={item.staging_rows}, "\n            f"manual_specs={item.manual_specs}, mapping={item.mapping_rows}"\n        )\n    if output_file.exists():\n        print(f"output_file: {output_file} ({output_file.stat().st_size:,} bytes)")\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(description="Load MI Master mapping_table parquet.")\n    parser.add_argument("--input-file", type=Path, default=DEFAULT_INPUT_FILE)\n    parser.add_argument("--catalog-path", type=Path, default=DEFAULT_CATALOG_PATH)\n    parser.add_argument("--output-file", type=Path, default=DEFAULT_OUTPUT_FILE)\n    return parser.parse_args()\n\n\ndef main() -> None:\n    args = parse_args()\n    xlsx_path = resolve_input_file(args.input_file)\n    records, stats = load_mapping_records(xlsx_path, args.catalog_path)\n    validate_records(records, stats)\n    write_parquet(records, args.output_file)\n    print_summary(records, stats, args.output_file)\n    print("validate_records: PASS")\n\n\nif __name__ == "__main__":\n    main()\n'

_SOURCE_P11 = '"""\nprototype_11_master_drug_to_parquet.py\n======================================\nMI Master drug rows -> Parquet.\n\nPhase 09e policy:\n- Canonical row-generation logic:\n  /Users/rexxa/github/jw-market/etl/master_loader.py::load_market_sheet\n- Canonical transform helpers:\n  /Users/rexxa/github/jw-market/etl/master_transform.py\n- Canonical schema:\n  /Users/rexxa/github/jw-market/sql/schema_master.sql,\n  stg_master_drug\n- Output schema is DDL columns only. No prototype helper columns such as\n  source_files or period are added.\n- Master drug parquet is a single file, not partitioned.\n\nUsage, in Step D after user review:\n    python3 scripts/prototype_11_master_drug_to_parquet.py\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport re\nimport sys\nfrom collections import Counter, defaultdict\nfrom dataclasses import dataclass\nfrom datetime import date, datetime, timezone\nfrom decimal import Decimal\nfrom pathlib import Path\nfrom typing import Any\n\ntry:\n    import pyarrow as pa\n    import pyarrow.parquet as pq\n    from openpyxl import load_workbook\nexcept ImportError as e:\n    sys.exit(f"ERROR: {e}\\n  pip3 install pyarrow openpyxl --break-system-packages")\n\n\nETL_DIR = Path(__file__).resolve().parent / "etl"\nsys.path.insert(0, str(ETL_DIR))\nfrom storage import get_mi_master_path  # noqa: E402\ntry:  # noqa: E402\n    from strategic_exclusion_policy import classify_exclusion_cells as classify_exclusion_cells_by_policy\nexcept ModuleNotFoundError:  # noqa: E402\n    from pipeline.scripts.strategic_exclusion_policy import classify_exclusion_cells as classify_exclusion_cells_by_policy\n\n\nDEFAULT_INPUT_FILE = get_mi_master_path()\nMASTER_ROOT = DEFAULT_INPUT_FILE.parent\nDEFAULT_CATALOG_PATH = Path("docs/reference/master_column_mapping_catalog.md")\nDEFAULT_OUTPUT_FILE = Path("parquet/master_drug/master_drug.parquet")\n\nSTANDARD_PREFIX = "drug_extra_json."\nEXPECTED_ROW_COUNT = 3952\nEXPECTED_EXCLUDED_ROWS = 543\nEXPECTED_SOURCE_TYPE_DISTRIBUTION = {"IQVIA": 650, "UBIST": 3302}\n\nMASTER_DRUG_COLUMNS = (\n    "strategic_market_id",\n    "market_name",\n    "source_type",\n    "drug_index",\n    "atc4_code",\n    "atc4_desc",\n    "molecule",\n    "product_name",\n    "manufacturer",\n    "seller",\n    "pack_desc",\n    "nhi_type",\n    "class",\n    "class_2",\n    "dosage_form",\n    "administration_route",\n    "strength",\n    "strength_raw",\n    "strength_raw_2",\n    "formulation",\n    "funnel",\n    "ox_gx",\n    "molecule_disease_definition",\n    "composition_type",\n    "drug_extra_json",\n    "raw_row_json",\n    "column_metadata_json",\n    "source_sheet",\n    "source_file_version",\n    "source_row_id",\n    "ingested_at",\n)\n\nJSON_COLUMNS = ("drug_extra_json", "raw_row_json", "column_metadata_json")\n\n\n@dataclass(frozen=True)\nclass MarketSheetConfig:\n    strategic_market_id: str\n    sheet_name: str\n    header_row: int\n    source_type: str\n\n\n@dataclass\nclass MarketDrugStats:\n    strategic_market_id: str\n    sheet_name: str\n    header_row: int\n    max_row: int\n    max_col: int\n    raw_rows_scanned: int = 0\n    empty_rows: int = 0\n    excluded_rows: int = 0\n    staging_rows: int = 0\n\n\nMARKET_SHEETS: tuple[MarketSheetConfig, ...] = (\n    MarketSheetConfig("strategy_001", "라베칸 라베칸듀오", 5, "UBIST"),\n    MarketSheetConfig("strategy_002", "제이클", 5, "IQVIA"),\n    MarketSheetConfig("strategy_003", "가드렛 가드메트", 5, "IQVIA"),\n    MarketSheetConfig("strategy_004", "타발리스", 5, "IQVIA"),\n    MarketSheetConfig("strategy_005", "시그마트", 5, "UBIST"),\n    MarketSheetConfig("strategy_006", "리바로 리바로젯", 4, "UBIST"),\n    MarketSheetConfig("strategy_007", "리바로페노", 4, "UBIST"),\n    MarketSheetConfig("strategy_008", "리바로하이 리바로브이", 5, "UBIST"),\n    MarketSheetConfig("strategy_009", "트루패스 피나스타 제이다트", 5, "UBIST"),\n    MarketSheetConfig("strategy_010", "뉴트로진 모빌리아", 5, "IQVIA"),\n    MarketSheetConfig("strategy_011", "악템라", 5, "IQVIA"),\n    MarketSheetConfig("strategy_012", "페린젝트 베노훼럼", 5, "IQVIA"),\n    MarketSheetConfig("strategy_013", "헴리브라", 5, "IQVIA"),\n    MarketSheetConfig("strategy_014", "위너프 위너프A+", 5, "IQVIA"),\n    MarketSheetConfig("strategy_015", "엔커버", 7, "IQVIA"),\n    MarketSheetConfig("strategy_016", "플라주오피", 5, "IQVIA"),\n)\n\nEXPECTED_MARKET_STATS = {\n    # 260518 시트들은 일부 시장에서 실제 데이터 아래에 formatting tail이 남아\n    # raw scan은 995행까지 이어진다. 이 표는 raw_rows_scanned/empty_rows를\n    # 그대로 기록하되, staging_rows가 실제 약품 행수라는 불변량을 잡는다.\n    # raw scan을 과거 짧은 row count에 맞추는 대안은 260518 Excel 형식을\n    # 정상 입력으로 처리하지 못해 기각했다.\n    "strategy_001": {"sheet_name": "라베칸 라베칸듀오", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 637, "excluded_rows": 0, "staging_rows": 358},\n    "strategy_002": {"sheet_name": "제이클", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 950, "excluded_rows": 0, "staging_rows": 45},\n    "strategy_003": {"sheet_name": "가드렛 가드메트", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 913, "excluded_rows": 0, "staging_rows": 82},\n    "strategy_004": {"sheet_name": "타발리스", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 985, "excluded_rows": 0, "staging_rows": 10},\n    "strategy_005": {"sheet_name": "시그마트", "header_row": 5, "raw_rows_scanned": 294, "empty_rows": 0, "excluded_rows": 0, "staging_rows": 294},\n    "strategy_006": {"sheet_name": "리바로 리바로젯", "header_row": 4, "raw_rows_scanned": 1295, "empty_rows": 200, "excluded_rows": 48, "staging_rows": 1047},\n    "strategy_007": {"sheet_name": "리바로페노", "header_row": 4, "raw_rows_scanned": 996, "empty_rows": 385, "excluded_rows": 494, "staging_rows": 117},\n    "strategy_008": {"sheet_name": "리바로하이 리바로브이", "header_row": 5, "raw_rows_scanned": 1096, "empty_rows": 15, "excluded_rows": 0, "staging_rows": 1081},\n    "strategy_009": {"sheet_name": "트루패스 피나스타 제이다트", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 589, "excluded_rows": 1, "staging_rows": 405},\n    "strategy_010": {"sheet_name": "뉴트로진 모빌리아", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 985, "excluded_rows": 0, "staging_rows": 10},\n    "strategy_011": {"sheet_name": "악템라", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 969, "excluded_rows": 0, "staging_rows": 26},\n    "strategy_012": {"sheet_name": "페린젝트 베노훼럼", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 919, "excluded_rows": 0, "staging_rows": 76},\n    "strategy_013": {"sheet_name": "헴리브라", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 981, "excluded_rows": 0, "staging_rows": 14},\n    "strategy_014": {"sheet_name": "위너프 위너프A+", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 664, "excluded_rows": 0, "staging_rows": 331},\n    "strategy_015": {"sheet_name": "엔커버", "header_row": 7, "raw_rows_scanned": 993, "empty_rows": 989, "excluded_rows": 0, "staging_rows": 4},\n    "strategy_016": {"sheet_name": "플라주오피", "header_row": 5, "raw_rows_scanned": 995, "empty_rows": 943, "excluded_rows": 0, "staging_rows": 52},\n}\n\n\ndef utc_now_text() -> str:\n    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")\n\n\ndef resolve_input_file(path: Path) -> Path:\n    if path.exists():\n        # Match the current project loader path semantics: scripts/load_master.py\n        # normally obtains this path from find_master_xlsx(), which returns the\n        # actual filesystem directory entry. On macOS that preserves the\n        # decomposed Korean filename in xlsx_path.name.\n        for candidate in sorted(file for file in path.parent.glob("*.xlsx") if not file.name.startswith("~$")):\n            try:\n                if candidate.samefile(path):\n                    return candidate\n            except FileNotFoundError:\n                continue\n        return path\n    candidates = sorted(file for file in MASTER_ROOT.glob("*.xlsx") if not file.name.startswith("~$"))\n    if not candidates:\n        raise FileNotFoundError(f"No Master xlsx found under {MASTER_ROOT}")\n    return candidates[-1]\n\n\ndef normalize_header(value: object) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    return text or None\n\n\ndef to_jsonable(value: Any) -> Any:\n    if isinstance(value, (datetime, date)):\n        return value.isoformat()\n    if isinstance(value, Decimal):\n        return float(value)\n    return value\n\n\ndef dumps_json(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, default=to_jsonable, sort_keys=True)\n\n\ndef is_empty_row(values: list[Any] | tuple[Any, ...]) -> bool:\n    return all(value is None or str(value).strip() == "" for value in values)\n\n\ndef _is_class_header(header: Any) -> bool:\n    text = normalize_header(header)\n    if not text:\n        return False\n    normalized = re.sub(r"[\\s_-]+", "", text).lower()\n    return normalized in {"class", "class1", "class2"} or normalized.startswith("class")\n\n\ndef _class_source_indexes(headers: list[Any] | tuple[Any, ...], metadata: dict[str, dict[str, Any]]) -> set[int]:\n    indexes: set[int] = {idx for idx, header in enumerate(headers) if _is_class_header(header)}\n    for target in ("class", "class_1", "class_2"):\n        spec = metadata.get(target) or {}\n        if spec.get("position") is not None:\n            try:\n                indexes.add(int(spec["position"]))\n            except (TypeError, ValueError):\n                pass\n            continue\n        source_column = normalize_header(spec.get("source_column"))\n        if not source_column:\n            continue\n        for idx, header in enumerate(headers):\n            text = normalize_header(header)\n            if text and (text == source_column or text.startswith(source_column)):\n                indexes.add(idx)\n    return indexes\n\n\ndef is_excluded_row(\n    values: list[Any] | tuple[Any, ...],\n    class_indexes: set[int] | None = None,\n    *,\n    strategic_market_id: str | None = None,\n    sheet_name: str | None = None,\n) -> bool:\n    class_indexes = set(class_indexes or ())\n    row_excluded, _class_excluded = classify_exclusion_cells_by_policy(\n        values,\n        class_indexes=class_indexes,\n        strategic_market_id=strategic_market_id,\n        sheet_name=sheet_name,\n    )\n    return row_excluded\n\n\ndef make_header_keys(headers: list[Any] | tuple[Any, ...]) -> list[str]:\n    seen: dict[str, int] = {}\n    keys: list[str] = []\n    for index, header in enumerate(headers, start=1):\n        normalized = normalize_header(header)\n        base = normalized if normalized is not None else f"__blank_col_{index}"\n        count = seen.get(base, 0) + 1\n        seen[base] = count\n        keys.append(base if count == 1 else f"{base}__{count}")\n    return keys\n\n\ndef build_raw_row_payload(\n    headers: list[Any] | tuple[Any, ...],\n    values: list[Any] | tuple[Any, ...],\n    source_row_id: int,\n) -> dict[str, Any]:\n    width = max(len(headers), len(values))\n    padded_headers = list(headers) + [None] * (width - len(headers))\n    padded_values = list(values) + [None] * (width - len(values))\n    keys = make_header_keys(padded_headers)\n    cells = []\n    values_by_header: dict[str, Any] = {}\n    for index, (header, key, value) in enumerate(zip(padded_headers, keys, padded_values), start=1):\n        json_value = to_jsonable(value)\n        cell = {\n            "column_index": index,\n            "header": normalize_header(header),\n            "header_key": key,\n            "value": json_value,\n        }\n        cells.append(cell)\n        values_by_header[key] = json_value\n    return {\n        "source_row_id": source_row_id,\n        "cells": cells,\n        "values_by_header": values_by_header,\n    }\n\n\ndef _header_lookup(headers: list[Any] | tuple[Any, ...], values: list[Any] | tuple[Any, ...]) -> dict[str, Any]:\n    lookup: dict[str, Any] = {}\n    for header, value in zip(headers, values):\n        normalized = normalize_header(header)\n        if normalized is not None and normalized not in lookup:\n            lookup[normalized] = value\n    return lookup\n\n\ndef _lookup_source_value(lookup: dict[str, Any], source_column: str | None) -> Any:\n    if source_column is None:\n        return None\n    if source_column in lookup:\n        return lookup[source_column]\n    for header, value in lookup.items():\n        if header.startswith(source_column):\n            return value\n    return None\n\n\ndef _lookup_position_value(values: list[Any] | tuple[Any, ...], position: Any) -> Any:\n    """Return a 0-based physical column value for blank-header source columns."""\n    if position is None:\n        return None\n    try:\n        column_index = int(position)\n    except (TypeError, ValueError):\n        raise ValueError(f"invalid catalog position: {position!r}") from None\n    if column_index < 0:\n        raise ValueError(f"catalog position must be >= 0: {position!r}")\n    if column_index >= len(values):\n        return None\n    return values[column_index]\n\n\ndef _extra_key(metadata_key: str) -> str:\n    return metadata_key[len(STANDARD_PREFIX) :]\n\n\ndef apply_column_mapping(\n    headers: list[Any] | tuple[Any, ...],\n    values: list[Any] | tuple[Any, ...],\n    metadata: dict[str, dict[str, Any]],\n) -> tuple[dict[str, Any], dict[str, Any]]:\n    lookup = _header_lookup(headers, values)\n    standard: dict[str, Any] = {}\n    extras: dict[str, Any] = {}\n    for target_column, spec in metadata.items():\n        source_column = normalize_header(spec.get("source_column"))\n        if "position" in spec and spec.get("position") is not None:\n            value = _lookup_position_value(values, spec.get("position"))\n        else:\n            value = _lookup_source_value(lookup, source_column)\n        if target_column.startswith(STANDARD_PREFIX):\n            extras[_extra_key(target_column)] = to_jsonable(value)\n        else:\n            standard[target_column] = value\n    return standard, extras\n\n\ndef _position_value(values: list[Any] | tuple[Any, ...], column_index: int) -> Any:\n    if column_index <= 0 or column_index > len(values):\n        return None\n    return values[column_index - 1]\n\n\ndef _lookup_key(*values: Any) -> tuple[str, ...] | None:\n    key: list[str] = []\n    for value in values:\n        if value is None:\n            return None\n        text = str(value).strip()\n        if not text:\n            return None\n        key.append(text)\n    return tuple(key)\n\n\ndef _single_lookup_key(value: Any) -> str | None:\n    if value is None:\n        return None\n    text = str(value).strip()\n    return text or None\n\n\ndef explicit_lookup_join(data_rows: list[tuple[int, tuple[Any, ...]]]) -> dict[int, dict[str, Any]]:\n    """Return strategy_008 lookup-derived standard column overwrites."""\n    lookup1: dict[tuple[str, str], dict[str, Any]] = {}\n    for _, values in data_rows:\n        key = _lookup_key(_position_value(values, 17), _position_value(values, 18))\n        if key and key not in lookup1:\n            lookup1[key] = {\n                "molecule": _position_value(values, 19),\n                "molecule_disease_definition": _position_value(values, 20),\n                "composition_type": _position_value(values, 21),\n                "class": _position_value(values, 22),\n            }\n\n    lookup2: dict[str, Any] = {}\n    for _, values in data_rows:\n        key = _single_lookup_key(_position_value(values, 25))\n        if key and key not in lookup2:\n            lookup2[key] = _position_value(values, 26)\n\n    overrides: dict[int, dict[str, Any]] = {}\n    for source_row_id, values in data_rows:\n        left_key = _lookup_key(_position_value(values, 2), _position_value(values, 3))\n        if not left_key or left_key not in lookup1:\n            continue\n        row_override = dict(lookup1[left_key])\n        molecule_key = _single_lookup_key(row_override.get("molecule"))\n        row_override["class_2"] = lookup2.get(molecule_key) if molecule_key else None\n        overrides[source_row_id] = row_override\n    return overrides\n\n\ndef load_column_metadata_catalog(path: Path) -> dict[str, dict[str, dict[str, Any]]]:\n    text = path.read_text(encoding="utf-8")\n    catalog: dict[str, dict[str, dict[str, Any]]] = {}\n    current_market: str | None = None\n    lines = iter(text.splitlines())\n    for line in lines:\n        heading = re.match(r"^###\\s+(strategy_\\d{3})\\s+—", line)\n        if heading:\n            current_market = heading.group(1)\n            continue\n        if current_market and line.strip() == "```json":\n            block: list[str] = []\n            for json_line in lines:\n                if json_line.strip() == "```":\n                    break\n                block.append(json_line)\n            catalog[current_market] = json.loads("\\n".join(block))\n            current_market = None\n    missing = sorted({config.strategic_market_id for config in MARKET_SHEETS} - set(catalog))\n    if missing:\n        raise ValueError(f"column metadata catalog missing markets: {missing}")\n    return catalog\n\n\ndef _headers_from_sheet(ws: Any, header_row: int) -> list[Any]:\n    return list(next(ws.iter_rows(min_row=header_row, max_row=header_row, values_only=True)))\n\n\ndef _blank_record() -> dict[str, Any]:\n    return {column: None for column in MASTER_DRUG_COLUMNS}\n\n\ndef load_drug_records(\n    xlsx_path: Path,\n    catalog_path: Path,\n    ingested_at: str | None = None,\n) -> tuple[list[dict[str, Any]], list[MarketDrugStats]]:\n    metadata_catalog = load_column_metadata_catalog(catalog_path)\n    timestamp = ingested_at or utc_now_text()\n    records: list[dict[str, Any]] = []\n    stats: list[MarketDrugStats] = []\n\n    wb = load_workbook(xlsx_path, read_only=True, data_only=True)\n    try:\n        for config in MARKET_SHEETS:\n            if config.sheet_name not in wb.sheetnames:\n                raise ValueError(f"required sheet not found: {config.sheet_name!r}; sheets={wb.sheetnames}")\n            ws = wb[config.sheet_name]\n            headers = _headers_from_sheet(ws, config.header_row)\n            metadata = metadata_catalog[config.strategic_market_id]\n            market_stats = MarketDrugStats(\n                strategic_market_id=config.strategic_market_id,\n                sheet_name=config.sheet_name,\n                header_row=config.header_row,\n                max_row=ws.max_row,\n                max_col=ws.max_column,\n            )\n            drug_index = 0\n\n            row_items = list(enumerate(\n                ws.iter_rows(min_row=config.header_row + 1, values_only=True),\n                start=config.header_row + 1,\n            ))\n            explicit_overrides = (\n                explicit_lookup_join(row_items) if config.strategic_market_id == "strategy_008" else {}\n            )\n            class_indexes = _class_source_indexes(headers, metadata)\n\n            for source_row_id, values in row_items:\n                market_stats.raw_rows_scanned += 1\n                if is_empty_row(values):\n                    market_stats.empty_rows += 1\n                    continue\n                raw_payload = build_raw_row_payload(headers, values, source_row_id)\n                if is_excluded_row(\n                    values,\n                    class_indexes,\n                    strategic_market_id=config.strategic_market_id,\n                    sheet_name=config.sheet_name,\n                ):\n                    market_stats.excluded_rows += 1\n                    continue\n\n                standard_values, extras = apply_column_mapping(headers, values, metadata)\n                if source_row_id in explicit_overrides:\n                    standard_values.update(explicit_overrides[source_row_id])\n                drug_index += 1\n                market_stats.staging_rows += 1\n\n                record = _blank_record()\n                record.update(\n                    {\n                        "strategic_market_id": config.strategic_market_id,\n                        "market_name": config.sheet_name,\n                        "source_type": config.source_type,\n                        "drug_index": drug_index,\n                        "drug_extra_json": dumps_json(extras),\n                        "raw_row_json": dumps_json(raw_payload),\n                        "column_metadata_json": dumps_json(metadata),\n                        "source_sheet": config.sheet_name,\n                        "source_file_version": xlsx_path.name,\n                        "source_row_id": source_row_id,\n                        "ingested_at": timestamp,\n                    }\n                )\n                for key, value in standard_values.items():\n                    if key in record:\n                        record[key] = value\n                records.append(record)\n            stats.append(market_stats)\n    finally:\n        wb.close()\n\n    return records, stats\n\n\ndef _count_by(records: list[dict[str, Any]], key: str) -> dict[str, int]:\n    counts: dict[str, int] = {}\n    for record in records:\n        value = str(record.get(key) or "")\n        counts[value] = counts.get(value, 0) + 1\n    return dict(sorted(counts.items()))\n\n\ndef _expected_extra_keys(metadata: dict[str, dict[str, Any]]) -> list[str]:\n    return sorted(key.split(".", 1)[1] for key in metadata if key.startswith(STANDARD_PREFIX))\n\n\ndef validate_records(\n    records: list[dict[str, Any]],\n    stats: list[MarketDrugStats],\n    catalog_path: Path,\n) -> None:\n    if len(records) != EXPECTED_ROW_COUNT:\n        raise ValueError(f"master_drug row count must be {EXPECTED_ROW_COUNT}, found {len(records)}")\n\n    expected_columns = set(MASTER_DRUG_COLUMNS)\n    for index, record in enumerate(records, start=1):\n        extra_columns = sorted(set(record) - expected_columns)\n        missing_columns = sorted(expected_columns - set(record))\n        if extra_columns or missing_columns:\n            raise ValueError(f"row {index} schema mismatch: extra={extra_columns}, missing={missing_columns}")\n\n    stats_by_market = {item.strategic_market_id: item for item in stats}\n    expected_market_ids = {config.strategic_market_id for config in MARKET_SHEETS}\n    if set(stats_by_market) != expected_market_ids:\n        raise ValueError(\n            f"market stats mismatch: expected={sorted(expected_market_ids)}, actual={sorted(stats_by_market)}"\n        )\n\n    total_excluded = 0\n    for market_id, expected in EXPECTED_MARKET_STATS.items():\n        actual = stats_by_market[market_id]\n        for field in ("sheet_name", "header_row", "raw_rows_scanned", "empty_rows", "excluded_rows", "staging_rows"):\n            actual_value = getattr(actual, field)\n            expected_value = expected[field]\n            if actual_value != expected_value:\n                raise ValueError(f"{market_id} {field} mismatch: expected={expected_value}, actual={actual_value}")\n        total_excluded += actual.excluded_rows\n    if total_excluded != EXPECTED_EXCLUDED_ROWS:\n        raise ValueError(f"excluded rows must be {EXPECTED_EXCLUDED_ROWS}, found {total_excluded}")\n\n    pk_values = [(record["strategic_market_id"], str(record["drug_index"])) for record in records]\n    if len(set(pk_values)) != EXPECTED_ROW_COUNT:\n        duplicate_keys = sorted({value for value in pk_values if pk_values.count(value) > 1})\n        raise ValueError(f"compound PK must be unique, duplicate examples={duplicate_keys[:10]}")\n\n    market_distribution = _count_by(records, "strategic_market_id")\n    expected_market_distribution = {\n        market_id: expected["staging_rows"] for market_id, expected in EXPECTED_MARKET_STATS.items()\n    }\n    if market_distribution != expected_market_distribution:\n        raise ValueError(\n            f"market distribution mismatch: expected={expected_market_distribution}, actual={market_distribution}"\n        )\n\n    source_type_distribution = _count_by(records, "source_type")\n    if source_type_distribution != EXPECTED_SOURCE_TYPE_DISTRIBUTION:\n        raise ValueError(\n            f"source_type distribution mismatch: expected={EXPECTED_SOURCE_TYPE_DISTRIBUTION}, "\n            f"actual={source_type_distribution}"\n        )\n\n    metadata_catalog = load_column_metadata_catalog(catalog_path)\n    records_by_market: dict[str, list[dict[str, Any]]] = defaultdict(list)\n    for record in records:\n        records_by_market[record["strategic_market_id"]].append(record)\n\n    for config in MARKET_SHEETS:\n        market_records = records_by_market[config.strategic_market_id]\n        expected_count = EXPECTED_MARKET_STATS[config.strategic_market_id]["staging_rows"]\n        drug_indexes = [int(record["drug_index"]) for record in market_records]\n        if drug_indexes != list(range(1, expected_count + 1)):\n            raise ValueError(\n                f"{config.strategic_market_id} drug_index sequence mismatch: "\n                f"expected=1..{expected_count}, actual_first_last={drug_indexes[:3]}...{drug_indexes[-3:]}"\n            )\n\n        metadata = metadata_catalog[config.strategic_market_id]\n        expected_metadata_json = dumps_json(metadata)\n        expected_extra_keys = _expected_extra_keys(metadata)\n        for record in market_records:\n            for column in JSON_COLUMNS:\n                try:\n                    json.loads(record[column])\n                except Exception as exc:\n                    raise ValueError(f"{config.strategic_market_id} {column} is not valid JSON") from exc\n\n            extra = json.loads(record["drug_extra_json"])\n            raw_payload = json.loads(record["raw_row_json"])\n            metadata_json = json.loads(record["column_metadata_json"])\n\n            if sorted(extra.keys()) != expected_extra_keys:\n                raise ValueError(\n                    f"{config.strategic_market_id} drug_extra_json keys mismatch: "\n                    f"expected={expected_extra_keys}, actual={sorted(extra.keys())}"\n                )\n            if record["column_metadata_json"] != expected_metadata_json:\n                raise ValueError(f"{config.strategic_market_id} column_metadata_json string mismatch")\n            if metadata_json != metadata:\n                raise ValueError(f"{config.strategic_market_id} column_metadata_json structure mismatch")\n            # 시트별 컬럼 수가 달라져도 raw_row_json의 cells와 values_by_header가\n            # 같은 폭을 유지하는지만 검증한다. 26칸 고정 검사는 260518의 컬럼\n            # 배치 변화를 버그로 오판하므로 기각했다.\n            expected_cell_count = len(raw_payload.get("values_by_header", {}))\n            if len(raw_payload.get("cells", [])) != expected_cell_count:\n                raise ValueError(\n                    f"{config.strategic_market_id} raw_row_json cells length mismatch: "\n                    f"expected={expected_cell_count}, actual={len(raw_payload.get(\'cells\', []))}"\n                )\n            if int(record["source_row_id"]) != int(raw_payload.get("source_row_id")):\n                raise ValueError(f"{config.strategic_market_id} source_row_id mismatch in raw_row_json")\n\n\ndef write_parquet(records: list[dict[str, Any]], output_file: Path) -> None:\n    output_file.parent.mkdir(parents=True, exist_ok=True)\n    schema = pa.schema([pa.field(column, pa.string()) for column in MASTER_DRUG_COLUMNS])\n    rows = [\n        {column: None if record[column] is None else str(record[column]) for column in MASTER_DRUG_COLUMNS}\n        for record in records\n    ]\n    table = pa.Table.from_pylist(rows, schema=schema)\n    pq.write_table(table, output_file, compression="zstd")\n\n\ndef print_summary(records: list[dict[str, Any]], stats: list[MarketDrugStats], output_file: Path) -> None:\n    print("Phase 09e master_drug load")\n    print(f"master_drug_rows: {len(records)}")\n    print(f"compound_pk_unique: {len({(record[\'strategic_market_id\'], str(record[\'drug_index\'])) for record in records})}")\n    print(f"source_type_distribution: {_count_by(records, \'source_type\')}")\n    print("market_distribution:")\n    for item in stats:\n        print(\n            f"  {item.strategic_market_id} {item.sheet_name}: "\n            f"raw={item.raw_rows_scanned}, empty={item.empty_rows}, "\n            f"excluded={item.excluded_rows}, staging={item.staging_rows}"\n        )\n    if records:\n        print(f"ingested_at: {records[0][\'ingested_at\']}")\n    if output_file.exists():\n        print(f"output_file: {output_file} ({output_file.stat().st_size:,} bytes)")\n\n\ndef parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(description="Load MI Master drug parquet.")\n    parser.add_argument("--input-file", type=Path, default=DEFAULT_INPUT_FILE)\n    parser.add_argument("--catalog-path", type=Path, default=DEFAULT_CATALOG_PATH)\n    parser.add_argument("--output-file", type=Path, default=DEFAULT_OUTPUT_FILE)\n    return parser.parse_args()\n\n\ndef main() -> None:\n    args = parse_args()\n    xlsx_path = resolve_input_file(args.input_file)\n    records, stats = load_drug_records(xlsx_path, args.catalog_path)\n    validate_records(records, stats, args.catalog_path)\n    write_parquet(records, args.output_file)\n    print_summary(records, stats, args.output_file)\n    print("validate_records: PASS")\n\n\nif __name__ == "__main__":\n    main()\n'


def run_master_market_definition(
    *,
    output_root: Path = PROJECT_ROOT,
    input_file: Path | None = None,
    ingested_at: str | None = None,
) -> MasterExtractResult:
    module = _load_prototype("p07", _SOURCE_P07)
    _pin_ingested_at(module, ingested_at)
    xlsx_path = Path(input_file or get_mi_master_path())
    output_path = _output(output_root, "parquet/master_market_definition/master_market_definition.parquet")
    records = list(module.iter_market_definition_rows(xlsx_path, ingested_at=ingested_at))
    module.validate_records(records)
    module.write_parquet(records, output_path)
    return _result("master_market_definition", output_path)


